"use client";
import {useEffect,useMemo,useState} from "react";
import type {ReactNode,ChangeEvent,KeyboardEvent} from "react";
import type {LucideIcon} from "lucide-react";
import {ChevronRight,Search,Bell,UserRound,Plus,Trash2,Pencil,WalletCards,TrendingUp,Package,Boxes,CakeSlice,ClipboardList,Users,ChartNoAxesCombined,ArrowLeft,CheckCircle2,CalendarDays,ArrowUpRight,ArrowDownRight,CircleDollarSign,Truck} from "lucide-react";
import type {AppData,Customer,Ingredient,Order,OrderStatus,Product,Expense,OrderActivity} from "@/types";
import {Badge,Button,Card,EmptyState,Input,Modal,Select,StockAlert,Textarea} from "./ui";
import {calculateIngredientCost,calculateIngredientUnitCost,calculateMargin,calculateOrderCost,calculateOrderIngredientCost,calculateRealCost,calculateSuggestedPrice,toBaseQuantity} from "@/lib/calculations";
import {clearData,restoreDemoData} from "@/lib/storage";
import {createDemoData} from "@/data/demo";
const money=(n:number)=>new Intl.NumberFormat("es-AR",{style:"currency",currency:"ARS",maximumFractionDigits:0}).format(n||0);
const compatibleUnits=(base:Ingredient["baseUnit"]):Ingredient["baseUnit"][]=>base==="g"||base==="kg"?["g","kg"]:base==="ml"||base==="l"?["ml","l"]:["unidad"];
const today=()=>{const d=new Date();const y=d.getFullYear();const m=String(d.getMonth()+1).padStart(2,"0");const day=String(d.getDate()).padStart(2,"0");return `${y}-${m}-${day}`};
function Section({title,children,action}:any){return <section className="space-y-3"><div className="flex items-center justify-between"><h2 className="serif text-xl font-semibold">{title}</h2>{action}</div>{children}</section>}
function NewOrderCakeButton({onClick}:{onClick:()=>void}){
 return <button type="button" onClick={onClick} className="new-order-cake-button" aria-label="Nuevo pedido">
   <span className="new-order-cake-illustration" aria-hidden="true">
     <svg viewBox="0 0 72 58" width="58" height="47" fill="none">
       <path d="M11 27h50l-4 23H15L11 27Z" fill="#F3C6C1" stroke="#49332D" strokeWidth="2.2" strokeLinejoin="round"/>
       <path d="M14 34h44" stroke="#E99A94" strokeWidth="2" strokeLinecap="round"/>
       <path d="M17 20h38l-3 11H20l-3-11Z" fill="#E99A94" stroke="#49332D" strokeWidth="2.2" strokeLinejoin="round"/>
       <path d="M20 20c0-6 5-10 11-10 2-5 9-6 13-2 2 2 3 4 3 7 5 0 8 2 9 5H20Z" fill="#FFFDF8" stroke="#49332D" strokeWidth="2.2" strokeLinejoin="round"/>
       <path d="M25 21c3-2 7-2 10 0M40 21c3-2 6-2 9 0" stroke="#F3C6C1" strokeWidth="2" strokeLinecap="round"/>
       <circle cx="36" cy="7" r="2.7" fill="#F7DDA8" stroke="#49332D" strokeWidth="1.4"/>
       <circle cx="28" cy="29" r="1.7" fill="#F7DDA8"/>
       <circle cx="45" cy="39" r="1.7" fill="#B9C9A8"/>
       <path d="M23 43h6M35 43h7M46 45h4" stroke="#FFFDF8" strokeWidth="2" strokeLinecap="round" opacity=".9"/>
     </svg>
   </span>
   <span className="new-order-cake-label">Nuevo pedido</span>
 </button>
}
function Stat({label,value,icon:Icon,sub}:{label:string;value:ReactNode;icon:LucideIcon;sub?:string}){return <Card className="p-4"><div className="flex items-start justify-between"><div><div className="text-xs font-medium text-[var(--muted)]">{label}</div><div className="mt-1 text-xl font-bold">{value}</div>{sub&&<div className="mt-1 text-xs text-[var(--muted)]">{sub}</div>}</div><div className="rounded-xl bg-[var(--bg)] p-2 text-[var(--primary)]"><Icon size={18}/></div></div></Card>}
export function Dashboard({data,onNavigate,onAttention,onQuickAction}:{data:AppData;onNavigate:(id:string)=>void;onAttention:()=>void;onQuickAction:(type:"order"|"ingredient"|"product"|"expense")=>void}){
 const todayKey=today();
 const now=new Date();
 const todayOrders=data.orders.filter((o:Order)=>o.deliveryDate===todayKey&&o.status!=="Cancelado"&&o.status!=="Entregado");
 const lowStock=data.ingredients.filter((i:Ingredient)=>i.stock<=i.minimumStock);
 const overdue=data.orders.filter((o:Order)=>o.status!=="Cancelado"&&o.balance>0&&o.deliveryDate<todayKey);
 const pendingPayments=data.orders.filter((o:Order)=>o.status!=="Cancelado"&&o.balance>0);
 const prepare=todayOrders.filter((o:Order)=>["Pendiente","Confirmado","En preparación"].includes(o.status));
 const deliver=todayOrders.filter((o:Order)=>!prepare.some((p:Order)=>p.id===o.id));
 const collect=todayOrders.filter((o:Order)=>o.balance>0);
 const upcoming=[...data.orders]
   .filter((o:Order)=>o.status!=="Entregado"&&o.status!=="Cancelado"&&(o.deliveryDate>todayKey||o.deliveryDate===todayKey))
   .sort((a:Order,b:Order)=>`${a.deliveryDate} ${a.deliveryTime}`.localeCompare(`${b.deliveryDate} ${b.deliveryTime}`))
   .slice(0,4);

 type Attention={id:string;priority:"urgent"|"important"|"attention";title:string;detail:string;section:string};
 const attention:Attention[]=[];
 overdue.slice(0,2).forEach((o:Order)=>{
   const customer=data.customers.find((c:Customer)=>c.id===o.customerId)?.name||"Cliente";
   attention.push({id:`overdue-${o.id}`,priority:"urgent",title:`Cobrar ${money(o.balance)} a ${customer}`,detail:"Pago vencido",section:"orders"});
 });
 pendingPayments.filter((o:Order)=>!overdue.some((x:Order)=>x.id===o.id)).slice(0,2).forEach((o:Order)=>{
   const customer=data.customers.find((c:Customer)=>c.id===o.customerId)?.name||"Cliente";
   attention.push({id:`payment-${o.id}`,priority:"important",title:`Cobrar ${money(o.balance)} a ${customer}`,detail:"Pago pendiente",section:"orders"});
 });
 todayOrders.slice(0,2).forEach((o:Order)=>{
   const product=o.items[0]?.productName||"Pedido";
   attention.push({id:`delivery-${o.id}`,priority:"important",title:`Preparar ${product}`,detail:`Entrega hoy · ${o.deliveryTime}`,section:"orders"});
 });
 lowStock.slice(0,3).forEach((i:Ingredient)=>attention.push({id:`stock-${i.id}`,priority:"attention",title:`Stock bajo: ${i.name}`,detail:`Quedan ${i.stock} ${i.baseUnit}`,section:"inventory"}));
 const visibleAttention=attention.slice(0,4);
 const customerName=(o:Order)=>data.customers.find((c:Customer)=>c.id===o.customerId)?.name||"Cliente";
 const dateLabel=(date:string)=>{
   if(date===todayKey)return "Hoy";
   const tomorrow=new Date(now); tomorrow.setDate(tomorrow.getDate()+1);
   const tomorrowKey=tomorrow.toISOString().slice(0,10);
   if(date===tomorrowKey)return "Mañana";
   return new Intl.DateTimeFormat("es-AR",{weekday:"long",day:"numeric",month:"short"}).format(new Date(`${date}T12:00:00`));
 };
 const itemLabel=(o:Order)=>o.items.length>1?`${o.items[0]?.productName||"Pedido"} + ${o.items.length-1} más`:o.items[0]?.quantity&&o.items[0].quantity>1?`${o.items[0].quantity} × ${o.items[0].productName}`:o.items[0]?.productName||"Pedido";
 const task=(o:Order,kind:"prepare"|"deliver"|"collect")=>{
   const title=kind==="collect"?customerName(o):itemLabel(o);
   const time=kind==="collect"?money(o.balance):o.deliveryTime||"Sin hora";
   return <button key={`${kind}-${o.id}`} onClick={()=>onNavigate("orders")} className="flex w-full items-center justify-between gap-4 rounded-xl border border-[var(--border)] bg-[var(--bg)] px-4 py-3 text-left transition hover:border-[var(--primary)] hover:bg-[var(--surface)]"><div className="min-w-0"><div className="truncate text-sm font-semibold">{title}</div>{kind!=="collect"&&<div className="mt-0.5 text-xs text-[var(--muted)]">{customerName(o)}</div>}</div><span className="shrink-0 text-sm font-semibold">{time}</span></button>;
 };
 const priorityTone=(priority:Attention["priority"])=>priority==="urgent"?"bg-[var(--primary)]":priority==="important"?"bg-[var(--accent)]":"bg-[var(--success)]";
 const attentionIcon=(a:Attention)=>a.id.startsWith("overdue-")||a.id.startsWith("payment-")?CircleDollarSign:a.id.startsWith("delivery-")?CakeSlice:Package;
 const greeting=data.userProfile.name?.trim()||data.businessProfile.businessName?.trim()||"Tu pastelería";
 const [businessPeriod,setBusinessPeriod]=useState<"today"|"yesterday"|"month"|"custom">("today");
 const [businessStartDate,setBusinessStartDate]=useState(todayKey);
 const [businessEndDate,setBusinessEndDate]=useState(todayKey);
 const [showBusinessCalendar,setShowBusinessCalendar]=useState(false);
 const businessRange=useMemo(()=>{
   const start=new Date(now);
   const end=new Date(now);
   if(businessPeriod==="today"){start.setHours(0,0,0,0);end.setHours(23,59,59,999);}
   else if(businessPeriod==="yesterday"){start.setDate(start.getDate()-1);start.setHours(0,0,0,0);end.setDate(end.getDate()-1);end.setHours(23,59,59,999);}
   else if(businessPeriod==="month"){start.setDate(1);start.setHours(0,0,0,0);end.setHours(23,59,59,999);}
   else {
     const customStart=new Date(`${businessStartDate}T00:00:00`);
     const customEnd=new Date(`${businessEndDate}T23:59:59.999`);
     if(customStart<=customEnd){return {start:customStart,end:customEnd};}
     return {start:customEnd,end:new Date(`${businessStartDate}T23:59:59.999`)};
   }
   return {start,end};
 },[businessPeriod,businessStartDate,businessEndDate]);
 const businessOrders=data.orders.filter((o:Order)=>{const dateKey=o.orderDate||o.createdAt?.slice(0,10)||todayKey;const d=new Date(`${dateKey}T12:00:00`);return d>=businessRange.start&&d<=businessRange.end&&o.status!=="Cancelado";});
 const businessSales=businessOrders.reduce((sum:number,o:Order)=>sum+o.total,0);
 const businessCosts=businessOrders.reduce((sum:number,o:Order)=>sum+calculateOrderCost(o,data.products,data.ingredients),0);
 const businessExpenses=data.expenses.filter((e:Expense)=>{const d=new Date(`${e.date}T12:00:00`);return d>=businessRange.start&&d<=businessRange.end;}).reduce((sum:number,e:Expense)=>sum+e.amount,0);
 const businessProfit=businessSales-businessCosts-businessExpenses;
 const activeOrdersCount=data.orders.filter((o:Order)=>o.status!=="Cancelado"&&o.status!=="Entregado").length;
 const previousBusinessRange=useMemo(()=>{
   const duration=Math.max(1,businessRange.end.getTime()-businessRange.start.getTime());
   const end=new Date(businessRange.start.getTime()-1);
   const start=new Date(end.getTime()-duration);
   return {start,end};
 },[businessRange]);
 const previousBusinessSales=data.orders.filter((o:Order)=>{const dateKey=o.orderDate||o.createdAt?.slice(0,10)||todayKey;const d=new Date(`${dateKey}T12:00:00`);return d>=previousBusinessRange.start&&d<=previousBusinessRange.end&&o.status!=="Cancelado";}).reduce((sum:number,o:Order)=>sum+o.total,0);
 const businessTrend=previousBusinessSales>0?((businessSales-previousBusinessSales)/previousBusinessSales)*100:null;
 return <div className="space-y-8">
   <div className="flex items-center justify-between gap-4 sm:gap-6">
     <div className="min-w-0 flex-1">
       <p className="text-sm text-[var(--muted)]">Buenos días 👋</p>
       <h1 className="serif text-3xl font-bold sm:text-4xl">{greeting}</h1>
       <p className="mt-1 text-sm text-[var(--muted)]">Así va tu negocio hoy</p>
     </div>
</div>

   <section aria-labelledby="business-title" className="space-y-3 bakery-business">
     <div className="flex items-center justify-between gap-3">
       <h2 id="business-title" className="serif text-xl font-semibold">Mi negocio</h2>
       <div className="relative">
         <button type="button" aria-label="Elegir período personalizado" aria-expanded={showBusinessCalendar} onClick={()=>setShowBusinessCalendar(v=>!v)} className={`flex h-9 w-9 items-center justify-center rounded-xl border transition ${businessPeriod==="custom"?"border-[var(--primary)] bg-[var(--bg)] text-[var(--primary)]":"border-[var(--border)] bg-[var(--surface)] text-[var(--muted)] hover:text-[var(--primary)]"}`}>
           <CalendarDays size={17}/>
         </button>
         {showBusinessCalendar&&<div className="absolute right-0 top-11 z-20 w-72 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 shadow-xl">
           <div className="mb-3"><div className="text-sm font-semibold">Elegir período</div><div className="mt-0.5 text-xs text-[var(--muted)]">Desde una fecha hasta otra.</div></div>
           <div className="grid grid-cols-2 gap-3">
             <label className="space-y-1"><span className="text-[10px] font-semibold uppercase tracking-wide text-[var(--muted)]">Desde</span><input type="date" value={businessStartDate} onChange={e=>{setBusinessStartDate(e.target.value);setBusinessPeriod("custom")}} className="h-10 w-full rounded-xl border border-[var(--border)] bg-[var(--bg)] px-2 text-xs outline-none focus:border-[var(--primary)]"/></label>
             <label className="space-y-1"><span className="text-[10px] font-semibold uppercase tracking-wide text-[var(--muted)]">Hasta</span><input type="date" value={businessEndDate} onChange={e=>{setBusinessEndDate(e.target.value);setBusinessPeriod("custom")}} className="h-10 w-full rounded-xl border border-[var(--border)] bg-[var(--bg)] px-2 text-xs outline-none focus:border-[var(--primary)]"/></label>
           </div>
           <div className="mt-3 flex justify-end"><button type="button" onClick={()=>setShowBusinessCalendar(false)} className="rounded-lg px-3 py-2 text-xs font-semibold text-[var(--primary)] hover:bg-[var(--bg)]">Aplicar</button></div>
         </div>}
       </div>
     </div>
     <div className="flex gap-1 rounded-[14px] border border-[var(--border)] bg-[var(--surface)] p-1 shadow-[var(--shadow-soft)]" role="tablist" aria-label="Período de estadísticas">
       {(["today","yesterday","month"] as const).map((tab)=><button key={tab} type="button" role="tab" aria-selected={businessPeriod===tab} onClick={()=>setBusinessPeriod(tab)} className={`flex-1 rounded-[11px] px-3 py-2 text-xs font-semibold transition ${businessPeriod===tab?"bg-[var(--primary)] text-white":"text-[var(--muted)] hover:text-[var(--text)]"}`}>{tab==="today"?"Hoy":tab==="yesterday"?"Ayer":"Mes"}</button>)}
     </div>
     {businessPeriod==="custom"&&<div className="text-xs text-[var(--muted)]">Período: {new Intl.DateTimeFormat("es-AR",{day:"2-digit",month:"2-digit",year:"numeric"}).format(new Date(`${businessStartDate}T12:00:00`))} → {new Intl.DateTimeFormat("es-AR",{day:"2-digit",month:"2-digit",year:"numeric"}).format(new Date(`${businessEndDate}T12:00:00`))}</div>}
     <div key={businessPeriod} className="grid gap-3 sm:grid-cols-3 bakery-metrics business-period-transition">
       <Card className="bakery-metric bakery-surface p-4 pt-5 sm:p-5 sm:pt-5"><div className="flex items-start justify-between gap-4"><div><div className="text-[11px] font-semibold uppercase tracking-[.12em] text-[var(--muted)]">Ventas</div><div className="mt-1 text-2xl font-bold tracking-[-.04em] sm:text-[28px]">{money(businessSales)}</div><div className={`mt-2 flex items-center gap-1 text-[11px] font-semibold ${businessTrend===null?"text-[var(--muted)]":businessTrend>=0?"text-[var(--success)]":"text-[var(--danger)]"}`}>{businessTrend===null?"Sin período comparable":businessTrend>=0?<ArrowUpRight size={14}/>:<ArrowDownRight size={14}/>} {businessTrend===null?"":`${Math.abs(businessTrend).toFixed(0)}% respecto al período anterior`}</div></div><div className="rounded-[13px] bg-[var(--bg)] p-2.5 text-[var(--primary)]"><WalletCards size={18}/></div></div></Card>
       <Card className="bakery-metric bakery-surface p-4 pt-5 sm:p-5 sm:pt-5"><div className="flex items-start justify-between gap-4"><div><div className="text-[11px] font-semibold uppercase tracking-[.12em] text-[var(--muted)]">Costos de productos</div><div className="mt-1 text-2xl font-bold tracking-[-.04em] sm:text-[28px]">{money(businessCosts)}</div><div className="mt-2 text-[11px] font-medium text-[var(--muted)]">Costo registrado del período</div></div><div className="rounded-[13px] bg-[var(--bg)] p-2.5 text-[var(--primary)]"><CakeSlice size={18}/></div></div></Card>
       <Card className="bakery-metric bakery-surface p-4 pt-5 sm:p-5 sm:pt-5"><div className="flex items-start justify-between gap-4"><div><div className="text-[11px] font-semibold uppercase tracking-[.12em] text-[var(--muted)]">Ganancias</div><div className={`mt-1 flex items-center gap-1.5 text-2xl font-bold tracking-[-.04em] sm:text-[28px] ${businessProfit>0?"text-[var(--success)]":businessProfit<0?"text-[var(--danger)]":"text-[var(--text)]"}`}>{businessProfit>0?<ArrowUpRight size={20}/>:businessProfit<0?<ArrowDownRight size={20}/>:null}<span>{money(businessProfit)}</span></div><div className={`mt-2 text-[11px] font-semibold ${businessProfit>0?"text-[var(--success)]":businessProfit<0?"text-[var(--danger)]":"text-[var(--muted)]"}`}>{businessProfit>0?"Resultado positivo":businessProfit<0?"Resultado negativo":"Sin resultado"}</div></div><div className={`rounded-[13px] bg-[var(--bg)] p-2.5 ${businessProfit>0?"text-[var(--success)]":businessProfit<0?"text-[var(--danger)]":"text-[var(--muted)]"}`}><TrendingUp size={18}/></div></div></Card>
            <Card className="bakery-metric bakery-surface p-4 pt-5 sm:col-start-3 sm:p-5 sm:pt-5"><div className="flex items-start justify-between gap-4"><div><div className="text-[11px] font-semibold uppercase tracking-[.12em] text-[var(--muted)]">Pedidos activos</div><div className="mt-1 text-2xl font-bold tracking-[-.04em] sm:text-[28px]">{activeOrdersCount}</div><div className="mt-2 text-[11px] font-medium text-[var(--muted)]">Pedidos pendientes o en proceso</div></div><div className="rounded-[13px] bg-[var(--bg)] p-2.5 text-[var(--primary)]"><ClipboardList size={18}/></div></div></Card>
     </div>
     <div className="space-y-3 pt-2">
       <div className="flex items-center justify-between"><h3 className="text-sm font-semibold">Accesos rápidos</h3><span className="text-xs text-[var(--muted)]">Empezá una tarea</span></div>
       <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
         <button type="button" onClick={()=>onQuickAction("order")} className="relative flex min-h-24 flex-col items-start justify-between overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left transition hover:border-[var(--primary)] hover:bg-[var(--bg)]"><span className="rounded-xl bg-[var(--bg)] p-2 text-[var(--primary)]"><ClipboardList size={18}/></span><span className="text-sm font-semibold">Nuevo pedido</span>
         </button>
         <button type="button" onClick={()=>onQuickAction("ingredient")} className="relative flex min-h-24 flex-col items-start justify-between overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left transition hover:border-[var(--primary)] hover:bg-[var(--bg)]"><span className="rounded-xl bg-[var(--bg)] p-2 text-[var(--primary)]"><Package size={18}/></span><span className="text-sm font-semibold">Cargar ingrediente</span>
         </button>
         <button type="button" onClick={()=>onQuickAction("product")} className="relative flex min-h-24 flex-col items-start justify-between overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left transition hover:border-[var(--primary)] hover:bg-[var(--bg)]"><span className="rounded-xl bg-[var(--bg)] p-2 text-[var(--primary)]"><CakeSlice size={18}/></span><span className="text-sm font-semibold">Crear receta</span>
         </button>
         <button type="button" onClick={()=>onQuickAction("expense")} className="relative flex min-h-24 flex-col items-start justify-between overflow-hidden rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left transition hover:border-[var(--primary)] hover:bg-[var(--bg)]"><span className="rounded-xl bg-[var(--bg)] p-2 text-[var(--primary)]"><WalletCards size={18}/></span><span className="text-sm font-semibold">Agregar gasto</span>
         </button>
       </div>
     </div>
   </section>

   <section aria-labelledby="attention-title" className="space-y-3">
     <div className="flex items-center justify-between gap-3">
       <div className="flex items-center gap-2"><Bell size={18} className="text-[var(--primary)]"/><h2 id="attention-title" className="serif text-xl font-semibold">Atención</h2></div>
       {attention.length>0&&<Button variant="ghost" onClick={onAttention}>Ver todo <ChevronRight className="inline" size={16}/></Button>}
     </div>
     <Card className="bakery-surface p-2.5 pt-5 sm:p-3 sm:pt-5">
       {visibleAttention.length>0?<div className="space-y-1">{visibleAttention.map(a=>{const Icon=attentionIcon(a);return <button key={a.id} onClick={()=>onNavigate(a.section)} className="group flex w-full items-center gap-3 rounded-[14px] px-3 py-3 text-left transition hover:bg-[var(--bg)] active:scale-[.995]"><span className="relative flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[var(--bg)] text-[var(--primary)]"><Icon size={17}/><span className={`absolute -right-0.5 -top-0.5 h-2 w-2 rounded-full ${priorityTone(a.priority)}`} aria-hidden="true"/></span><span className="min-w-0 flex-1"><span className="block text-sm font-semibold">{a.title}</span><span className="mt-0.5 block text-xs text-[var(--muted)]">{a.detail}</span></span><ChevronRight size={16} className="shrink-0 text-[var(--muted)] transition group-hover:translate-x-0.5"/></button>})}</div>:<div className="flex items-center gap-3 px-2 py-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[var(--bg)] text-[var(--success)]"><CheckCircle2 size={18}/></span><div><div className="text-sm font-semibold">Todo en orden</div><div className="text-xs text-[var(--muted)]">No tenés tareas pendientes importantes.</div></div></div>}
     </Card>
   </section>

   <section aria-labelledby="today-title" className="space-y-3">
     <div className="flex items-center justify-between"><h2 id="today-title" className="serif text-xl font-semibold">Para hoy</h2>{todayOrders.length>0&&<span className="text-xs text-[var(--muted)]">{todayOrders.length} pedido{todayOrders.length===1?"":"s"}</span>}</div>
     <Card className="p-4 sm:p-5">
       {prepare.length===0&&deliver.length===0&&collect.length===0?<div className="flex items-center gap-3 py-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[var(--bg)] text-[var(--success)]"><CheckCircle2 size={18}/></span><div><div className="text-sm font-semibold">Hoy estás al día</div><div className="text-xs text-[var(--muted)]">No tenés tareas pendientes para hoy.</div></div></div>:<div className="space-y-5">
         {prepare.length>0&&<div><div className="mb-2 flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-[var(--warning)]"><CakeSlice size={14}/>Preparar</div><div className="space-y-2">{prepare.sort((a:Order,b:Order)=>a.deliveryTime.localeCompare(b.deliveryTime)).map(o=>task(o,"prepare"))}</div></div>}
         {deliver.length>0&&<div><div className="mb-2 flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-sky-400"><Truck size={14}/>Entregar</div><div className="space-y-2">{deliver.sort((a:Order,b:Order)=>a.deliveryTime.localeCompare(b.deliveryTime)).map(o=>task(o,"deliver"))}</div></div>}
         {collect.length>0&&<div><div className="mb-2 flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-[var(--success)]"><CircleDollarSign size={14}/>Cobrar</div><div className="space-y-2">{collect.sort((a:Order,b:Order)=>a.deliveryTime.localeCompare(b.deliveryTime)).map(o=>task(o,"collect"))}</div></div>}
       </div>}
     </Card>
   </section>

   <Section title="Próximos pedidos" action={<Button variant="ghost" onClick={()=>onNavigate("orders")}>Ver todos <ChevronRight className="inline" size={16}/></Button>}>
     {upcoming.length>0?<div className="space-y-2">{upcoming.map((o:Order)=><button key={o.id} onClick={()=>onNavigate("orders")} className="flex w-full items-center justify-between gap-4 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4 text-left transition hover:border-[var(--primary)]"><div className="min-w-0"><div className="truncate text-sm font-semibold">{itemLabel(o)}</div><div className="mt-1 truncate text-xs text-[var(--muted)]">{customerName(o)} · {dateLabel(o.deliveryDate)} {o.deliveryTime}</div></div><Badge tone={o.balance>0?"warning":"success"}>{o.balance>0?"Pendiente de pago":"Pagado"}</Badge></button>)}</div>:<Card><EmptyState title="Todo tranquilo por ahora ✨" text="No tenés pedidos próximos."/></Card>}
   </Section>
 </div>;
}

export function Orders({data,update,onToast,createIntent}:any){
 const [modal,setModal]=useState(false);const [editing,setEditing]=useState<Order|null>(null);const [activityOrder,setActivityOrder]=useState<Order|null>(null);const [filter,setFilter]=useState("Todos");
 useEffect(()=>{if(createIntent==="order"){setEditing(null);setModal(true)}},[createIntent]);
 const filtered=data.orders.filter((o:Order)=>filter==="Todos"||o.status===filter);
 const statusTone=(status:OrderStatus)=>status==="Entregado"?"success":status==="Cancelado"?"danger":status==="Listo"?"success":"warning";
 function changeStatus(o:Order,status:OrderStatus){const now=new Date().toISOString();update((d:AppData)=>({...d,orders:d.orders.map(x=>x.id===o.id?{...x,status,updatedAt:now,activity:[...(x.activity||[]),{id:"act_"+Date.now(),type:"status",message:`Estado cambiado de ${x.status} a ${status}.`,createdAt:now}]}:x)}));onToast("Estado actualizado")}
 function openEdit(o:Order){setEditing(o);setModal(true)}
 return <div className="space-y-5">
  <PageHeader title="Pedidos" subtitle="Organizá entregas, estados, saldos y actividad." action={<NewOrderCakeButton onClick={()=>{setEditing(null);setModal(true)}}/>}/>
  <div className="flex gap-2 overflow-auto pb-1">{["Todos","Pendiente","Confirmado","En preparación","Listo","Entregado","Cancelado"].map(x=><button key={x} onClick={()=>setFilter(x)} className={`whitespace-nowrap rounded-full border px-3 py-2 text-xs font-medium ${filter===x?"border-[var(--primary)] bg-[var(--primary)] text-white":"border-[var(--border)] bg-[var(--surface)]"}`}>{x}</button>)}</div>
  {filtered.length?<div className="grid gap-3">{filtered.map((o:Order)=>{const customer=data.customers.find((c:Customer)=>c.id===o.customerId);return <Card key={o.id} className="overflow-hidden p-0">
   <div className="p-4 sm:p-5"><div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_180px_auto] lg:items-center">
    <div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><div className="truncate font-semibold">{customer?.name||"Sin cliente asignado"}</div><Badge tone={statusTone(o.status)}>{o.status}</Badge></div><div className="mt-1 text-sm text-[var(--muted)]">{o.items.map((i:any)=>`${i.productName} × ${i.quantity}`).join(", ")}</div><div className="mt-2 text-xs text-[var(--muted)]">Entrega: {o.deliveryDate} · {o.deliveryTime||"Sin horario"}</div>
     {(o.tags||[]).length>0&&<div className="mt-3 flex flex-wrap gap-1.5">{(o.tags||[]).map(tag=><span key={tag} className="inline-flex min-h-6 items-center rounded-full border border-[var(--border)] bg-[var(--bg)] px-2.5 py-1 text-[11px] font-medium">{tag}</span>)}</div>}
    </div>
    <div className="rounded-xl bg-[var(--bg)] p-3 lg:text-right"><div className="font-semibold">{money(o.total)}</div><div className="text-xs text-[var(--muted)]">Saldo {money(o.balance)}</div></div>
    <div className="flex flex-wrap items-center gap-2 lg:justify-end"><Button variant="ghost" onClick={()=>setActivityOrder(o)}>Historial</Button><Button variant="ghost" onClick={()=>openEdit(o)}><Pencil size={15}/> Editar</Button></div>
   </div>
   {o.status!=="Entregado"&&o.status!=="Cancelado"&&<div className="mt-4 flex flex-wrap items-center gap-2 border-t border-[var(--border)] pt-3"><span className="mr-1 text-xs text-[var(--muted)]">Cambiar estado:</span><Button onClick={()=>changeStatus(o,o.status==="Pendiente"?"En preparación":o.status==="En preparación"?"Listo":"Entregado")}>{o.status==="Pendiente"?"Pasar a preparación":o.status==="En preparación"?"Marcar listo":"Marcar entregado"}</Button></div>}
  </div></Card>})}</div>:<Card><EmptyState title="Todavía no hay pedidos" text="Cuando recibas tu primer pedido, aparecerá aquí." action={<Button onClick={()=>{setEditing(null);setModal(true)}}>Agregar pedido</Button>}/></Card>}
  {modal&&<OrderModal initial={editing} data={data} update={update} onClose={()=>setModal(false)} onToast={onToast}/>} {activityOrder&&<OrderActivityModal order={activityOrder} onClose={()=>setActivityOrder(null)}/>}</div>
}

function OrderModal({initial,data,update,onClose,onToast}:{initial:Order|null;data:AppData;update:any;onClose:()=>void;onToast:(s:string)=>void}){
 const makeItem=(p:Product):Order["items"][number]=>{const cost=calculateRealCost(p,data.ingredients);const ingredientCost=calculateIngredientCost(p,data.ingredients);return {productId:p.id,productName:p.name,quantity:1,unitPrice:p.price,subtotal:p.price,costUnitSnapshot:cost,costTotalSnapshot:cost,ingredientCostUnitSnapshot:ingredientCost,ingredientCostTotalSnapshot:ingredientCost}};
 const [customerId,setCustomerId]=useState(initial?.customerId||"");const [orderDate,setOrderDate]=useState(initial?.orderDate||initial?.createdAt?.slice(0,10)||today());const [items,setItems]=useState<Order["items"]>(initial?.items|| (data.products[0]?[makeItem(data.products[0])]:[]));const [date,setDate]=useState(initial?.deliveryDate||today());const [time,setTime]=useState(initial?.deliveryTime||"18:00");const [paid,setPaid]=useState(0);const [status,setStatus]=useState<OrderStatus>(initial?.status||"Pendiente");const [notes,setNotes]=useState(initial?.notes||"");const [tags,setTags]=useState<string[]>(initial?.tags||[]);const [tagInput,setTagInput]=useState("");
 const total=items.reduce((sum:number,i:Order["items"][number])=>sum+i.subtotal,0);const existingPaid=initial?.payments.reduce((sum,p)=>sum+p.amount,0)||0;const balance=Math.max(0,total-existingPaid-Number(paid));
 function syncItem(index:number,productId:string,quantity:number){const product=data.products.find(x=>x.id===productId);if(!product)return;const cost=calculateRealCost(product,data.ingredients);const ingredientCost=calculateIngredientCost(product,data.ingredients);setItems((xs:Order["items"])=>xs.map((x:Order["items"][number],i:number)=>i===index?{productId:product.id,productName:product.name,quantity,unitPrice:product.price,subtotal:product.price*quantity,costUnitSnapshot:x.productId===product.id&&x.costUnitSnapshot!==undefined?x.costUnitSnapshot:cost,costTotalSnapshot:(x.productId===product.id&&x.costUnitSnapshot!==undefined?x.costUnitSnapshot:cost)*quantity,ingredientCostUnitSnapshot:x.productId===product.id&&x.ingredientCostUnitSnapshot!==undefined?x.ingredientCostUnitSnapshot:ingredientCost,ingredientCostTotalSnapshot:(x.productId===product.id&&x.ingredientCostUnitSnapshot!==undefined?x.ingredientCostUnitSnapshot:ingredientCost)*quantity}:x))}
 function syncPrice(index:number,unitPrice:number){setItems((xs:Order["items"])=>xs.map((x:Order["items"][number],i:number)=>i===index?{...x,unitPrice,subtotal:unitPrice*x.quantity}:x))}
 function addItem(){const product=data.products[0];if(product)setItems((xs:Order["items"])=>[...xs,makeItem(product)])}
 const ingredientUsageForItems=(itemsToUse:Order["items"],products:Product[])=>{const usage:Record<string,number>={};itemsToUse.forEach(it=>{const product=products.find(p=>p.id===it.productId);if(!product)return;product.ingredients.forEach(r=>{const ing=data.ingredients.find(x=>x.id===r.ingredientId);if(!ing)return;usage[ing.id]=(usage[ing.id]||0)+toBaseQuantity(Number(r.quantity)||0,r.unit||ing.baseUnit)*it.quantity})});return usage};
function save(){if(!items.length||items.some((i:Order["items"][number])=>!i.productId||i.quantity<1)){onToast("Agregá al menos un producto válido");return}const now=new Date().toISOString();if(initial){const customerChanged=(initial.customerId||"")!==customerId;const statusChanged=initial.status!==status;const nextActivity=[...(initial.activity||[])];if(customerChanged)nextActivity.push({id:"act_"+Date.now()+"c",type:"customer",message:customerId?`Cliente asignado al pedido: ${data.customers.find(c=>c.id===customerId)?.name||"cliente"}.`:"Cliente quitado del pedido.",createdAt:now});if(statusChanged)nextActivity.push({id:"act_"+Date.now()+"s",type:"status",message:`Estado cambiado de ${initial.status} a ${status}.`,createdAt:now});const added=tags.filter((t:string)=>!(initial.tags||[]).includes(t));const removed=(initial.tags||[]).filter((t:string)=>!tags.includes(t));added.forEach((t:string)=>nextActivity.push({id:"act_"+Date.now()+t,type:"tag-added",message:`Etiqueta agregada: ${t}`,createdAt:now}));removed.forEach((t:string)=>nextActivity.push({id:"act_"+Date.now()+t,type:"tag-removed",message:`Etiqueta eliminada: ${t}`,createdAt:now}));nextActivity.push({id:"act_"+Date.now()+"e",type:"edited",message:"Pedido editado.",createdAt:now});update((d:AppData)=>({...d,orders:d.orders.map(o=>o.id===initial.id?{...o,customerId:customerId||undefined,orderDate,items,deliveryDate:date,deliveryTime:time,total,balance:Math.max(0,total-o.payments.reduce((sum:number,p:Order["payments"][number])=>sum+p.amount,0)),status,notes,tags,updatedAt:now,activity:nextActivity}:o)}));onToast("Pedido actualizado");onClose();return}
 const payment=Number(paid);const order:Order={id:"ord_"+Date.now(),customerId:customerId||undefined,orderDate,items,deliveryDate:date,deliveryTime:time,total,payments:payment?[{id:"pay_"+Date.now(),date:now,amount:payment,note:"Seña"}]:[],balance:Math.max(0,total-payment),status,notes,tags,createdAt:now,updatedAt:now,activity:[{id:"act_"+Date.now(),type:"created",message:"Pedido creado.",createdAt:now}]};const usage=ingredientUsageForItems(items,data.products);let lowStock=false;update((d:AppData)=>{const nextIngredients=d.ingredients.map(i=>{const used=usage[i.id]||0;if(!used)return i;const nextStock=i.stock-used;if(nextStock<0)lowStock=true;return {...i,stock:Math.max(0,nextStock),updatedAt:now}});return {...d,ingredients:nextIngredients,orders:[order,...d.orders],notifications:[{id:"n_"+Date.now(),type:"order",title:"Pedido nuevo",message:`Nuevo pedido${customerId?` de ${d.customers.find(c=>c.id===customerId)?.name||"cliente"}`:" sin cliente asignado"}.`,read:false,createdAt:now,relatedEntityId:order.id,relatedEntityType:"order"},...d.notifications]}});onToast(lowStock?"Pedido guardado. Algunos insumos quedaron sin stock suficiente.":"Pedido agregado correctamente");onClose()}
 function addTag(){const t=tagInput.trim();if(t&&!tags.includes(t))setTags([...tags,t]);setTagInput("")}
 return <Modal title={initial?"Editar pedido":"Nuevo pedido"} onClose={onClose} footer={<div className="flex w-full items-center justify-between gap-2"><div>{initial&&<Button variant="danger" onClick={()=>{if(!confirm("¿Eliminar este pedido? Se quitará de la lista de pedidos y esta acción no se puede deshacer desde la vista principal."))return;const now=new Date().toISOString();update((d:AppData)=>({...d,orders:d.orders.filter(o=>o.id!==initial.id),orderHistory:{...(d.orderHistory||{}),[initial.id]:[...(initial.activity||[]),{id:"act_"+Date.now(),type:"deleted",message:"Pedido eliminado.",createdAt:now}]}}));onToast("Pedido eliminado");onClose()}}><Trash2 size={15}/> Eliminar</Button>}</div><div className="flex gap-2"><Button variant="ghost" onClick={onClose}>Cancelar</Button><Button onClick={save}>{initial?"Guardar cambios":"Guardar pedido"}</Button></div></div>}><div className="space-y-4">
  <Select label="Cliente (opcional)" value={customerId} onChange={(e:ChangeEvent<HTMLSelectElement>)=>setCustomerId(e.target.value)}><option value="">Sin cliente asignado</option>{data.customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</Select>
  <div className="space-y-2"><div className="flex items-center justify-between"><label className="text-sm font-medium">Productos</label><Button variant="ghost" onClick={addItem}><Plus size={15}/> Agregar producto</Button></div>{items.map((item:Order["items"][number],index:number)=><div key={`${index}-${item.productId}`} className="grid gap-2 rounded-xl border border-[var(--border)] bg-[var(--bg)] p-3 sm:grid-cols-[minmax(0,1fr)_100px_auto]"><Select label="Producto" value={item.productId} onChange={(e:ChangeEvent<HTMLSelectElement>)=>syncItem(index,e.target.value,item.quantity)}>{data.products.map(p=><option key={p.id} value={p.id}>{p.name} · {money(p.price)}</option>)}</Select><Input label="Cantidad" type="number" min="1" value={item.quantity} onChange={(e:ChangeEvent<HTMLInputElement>)=>syncItem(index,item.productId,Math.max(1,Number(e.target.value)))} /><Input label="Precio unit." type="number" min="0" value={item.unitPrice} onChange={(e:ChangeEvent<HTMLInputElement>)=>syncPrice(index,Math.max(0,Number(e.target.value)))} />{items.length>1&&<button type="button" aria-label="Eliminar producto" onClick={()=>setItems((xs:Order["items"])=>xs.filter((_:Order["items"][number],i:number)=>i!==index))} className="mt-6 flex h-10 items-center justify-center rounded-xl border border-[var(--border)] px-3 text-[var(--danger)]"><Trash2 size={16}/></button>}</div>)}</div>
  <div className="grid grid-cols-2 gap-4"><Input label="Fecha del pedido" type="date" value={orderDate} onChange={(e:ChangeEvent<HTMLInputElement>)=>setOrderDate(e.target.value)}/><Select label="Estado" value={status} onChange={(e:ChangeEvent<HTMLSelectElement>)=>setStatus(e.target.value as OrderStatus)}>{["Pendiente","Confirmado","En preparación","Listo","Entregado","Cancelado"].map(x=><option key={x}>{x}</option>)}</Select></div>
  <div className="grid grid-cols-2 gap-4"><Input label="Fecha de entrega" type="date" value={date} onChange={(e:ChangeEvent<HTMLInputElement>)=>setDate(e.target.value)}/><Input label="Hora de entrega" type="time" value={time} onChange={(e:ChangeEvent<HTMLInputElement>)=>setTime(e.target.value)}/></div>
  {!initial&&<Input label="Seña / pago inicial" type="number" min="0" value={paid} onChange={(e:ChangeEvent<HTMLInputElement>)=>setPaid(Math.max(0,Number(e.target.value)))} />}
  <Textarea label="Notas" value={notes} onChange={(e:ChangeEvent<HTMLTextAreaElement>)=>setNotes(e.target.value)}/>
  <div><label className="text-sm font-medium">Etiquetas</label><div className="mt-2 flex gap-2"><Input label="" value={tagInput} onChange={(e:ChangeEvent<HTMLInputElement>)=>setTagInput(e.target.value)} onKeyDown={(e:KeyboardEvent<HTMLInputElement>)=>{if(e.key==="Enter"){e.preventDefault();addTag()}}} placeholder="Ej. urgente"/><Button variant="ghost" onClick={addTag}>Agregar</Button></div>{tags.length>0&&<div className="mt-2 flex flex-wrap gap-2">{tags.map((t:string)=><button key={t} onClick={()=>setTags(tags.filter((x:string)=>x!==t))} className="rounded-full bg-[var(--bg)] px-3 py-1 text-xs">{t} ×</button>)}</div>}</div>
  <Card className="bg-[var(--bg)] p-4"><div className="grid grid-cols-2 gap-3"><div><span className="text-xs text-[var(--muted)]">Total</span><div className="font-bold">{money(total)}</div></div><div><span className="text-xs text-[var(--muted)]">Saldo</span><div className="font-bold">{money(balance)}</div></div></div></Card>
 </div></Modal>
}

function OrderActivityModal({order,onClose}:{order:Order;onClose:()=>void}){const activity=[...(order.activity||[])].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return <Modal title="Historial del pedido" onClose={onClose}><div className="space-y-4">{activity.length?activity.map((a:OrderActivity)=><div key={a.id} className="relative flex gap-3"><div className="mt-1 flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-[var(--bg)] text-[var(--primary)]"><CheckCircle2 size={15}/></div><div className="min-w-0 flex-1 border-b border-[var(--border)] pb-3"><div className="text-sm font-medium">{a.message}</div><div className="mt-1 text-xs text-[var(--muted)]">{new Intl.DateTimeFormat("es-AR",{dateStyle:"short",timeStyle:"short"}).format(new Date(a.createdAt))}</div></div></div>):<EmptyState title="Sin actividad" text="Todavía no hay cambios registrados."/>}</div></Modal>}

function OrderDetail({order,data,update,onClose,onToast}:any){const [pay,setPay]=useState("");const customer=data.customers.find((c:Customer)=>c.id===order.customerId);const productionCost=calculateOrderCost(order,data.products,data.ingredients);const grossProfit=order.total-productionCost;function add(){const amount=Number(pay);if(!amount)return;const now=new Date().toISOString();update((d:AppData)=>({...d,orders:d.orders.map((o:Order)=>o.id===order.id?{...o,payments:[...o.payments,{id:"pay_"+Date.now(),date:now,amount,note:"Pago"}],balance:Math.max(0,o.balance-amount),updatedAt:now,activity:[...(o.activity||[]),{id:"act_"+Date.now(),type:"payment",message:`Pago registrado: ${money(amount)}.`,createdAt:now}]}:o)}));onToast("Pago registrado");setPay("")}return <Modal title="Detalle del pedido" onClose={onClose}><div className="space-y-5"><div><div className="text-lg font-semibold">{customer?.name||"Sin cliente asignado"}</div><div className="text-sm text-[var(--muted)]">{customer?.phone||"Sin teléfono"}</div></div><div className="space-y-2">{order.items.map((i:any)=><div key={i.productId} className="flex justify-between rounded-xl bg-[var(--bg)] p-3"><span>{i.productName} × {i.quantity}</span><b>{money(i.subtotal)}</b></div>)}</div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><Stat label="Ingreso" value={money(order.total)} icon={WalletCards}/><Stat label="Costo" value={money(productionCost)} icon={CakeSlice}/><Stat label="Ganancia bruta" value={money(grossProfit)} icon={TrendingUp}/><Stat label="Saldo" value={money(order.balance)} icon={TrendingUp}/></div><div className="flex gap-2"><Input label="Registrar pago" type="number" value={pay} onChange={(e:any)=>setPay(e.target.value)} placeholder="0"/><div className="pt-6"><Button onClick={add}>Registrar</Button></div></div><div className="text-sm text-[var(--muted)]">Estado: <b className="text-[var(--text)]">{order.status}</b></div></div></Modal>}

export function Customers({data,update,onToast,createIntent}:any){
 const [modal,setModal]=useState(false);useEffect(()=>{if(createIntent==="customer")setModal(true)},[createIntent]);
 const [editing,setEditing]=useState<Customer|null>(null);const [detail,setDetail]=useState<Customer|null>(null);const [orderDetail,setOrderDetail]=useState<Order|null>(null);const [q,setQ]=useState("");
 const list=data.customers.filter((c:Customer)=>`${c.name} ${c.businessName||""} ${c.contactName||""} ${c.phone}`.toLowerCase().includes(q.toLowerCase()));
 return <div className="space-y-5"><PageHeader title="Clientes" subtitle="Contactos e historial de pedidos." action={<Button onClick={()=>{setEditing(null);setModal(true)}}><Plus size={17}/> Nuevo cliente</Button>}/>
 <Input label="Buscar" placeholder="Nombre, negocio o teléfono" value={q} onChange={(e:ChangeEvent<HTMLInputElement>)=>setQ(e.target.value)}/>
 {list.length?<div className="grid gap-3 sm:grid-cols-2">{list.map((c:Customer)=>{const orders=data.orders.filter((o:Order)=>o.customerId===c.id);const spent=orders.reduce((s:number,o:Order)=>s+o.total,0);const balance=orders.reduce((s:number,o:Order)=>s+o.balance,0);const last=orders.slice().sort((a:Order,b:Order)=>((b.orderDate||b.createdAt).localeCompare(a.orderDate||a.createdAt)))[0];const displayName=c.name||c.businessName||"Cliente";return <Card key={c.id} className="p-4"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><div className="truncate font-semibold">{displayName}</div><span className="rounded-full border border-[var(--border)] px-2 py-0.5 text-[10px] font-semibold tracking-wide text-[var(--muted)]">{(c.type||"persona").toUpperCase()}</span></div><div className="mt-1 text-sm text-[var(--muted)]">{c.phone||"Sin teléfono"}</div></div><button aria-label="Editar cliente" title="Editar cliente" className="rounded-lg p-2 text-[var(--muted)] transition hover:bg-[var(--bg)] hover:text-[var(--text)]" onClick={()=>{setEditing(c);setModal(true)}}><Pencil size={17}/></button></div><div className="mt-4 grid grid-cols-3 gap-2 text-xs"><div><div className="text-[var(--muted)]">Pedidos</div><b>{orders.length}</b></div><div><div className="text-[var(--muted)]">Gastado</div><b>{money(spent)}</b></div><div><div className="text-[var(--muted)]">Pendiente</div><b className={balance>0?"text-[var(--warning)]":""}>{money(balance)}</b></div></div><div className="mt-3 text-xs text-[var(--muted)]">Último pedido: <span className="text-[var(--text)]">{last?formatCustomerDate(last.orderDate||last.createdAt):"Sin pedidos"}</span></div><div className="mt-4 flex items-center justify-start gap-2 border-t border-[var(--border)] pt-3"><Button variant="ghost" onClick={()=>setDetail(c)}>Ver cliente</Button></div></Card>})}</div>:<Card><EmptyState title="Todavía no hay clientes" text="Agregá tu primer cliente para empezar a registrar pedidos." action={<Button onClick={()=>setModal(true)}>Agendar cliente</Button>}/></Card>}
 {modal&&<CustomerModal initial={editing} update={update} onClose={()=>setModal(false)} onToast={onToast}/>} {detail&&<CustomerDetail customer={detail} data={data} onClose={()=>setDetail(null)} onEdit={()=>{setDetail(null);setEditing(detail);setModal(true)}} onOrder={(o:Order)=>setOrderDetail(o)}/>} {orderDetail&&<OrderDetail order={orderDetail} data={data} update={update} onClose={()=>setOrderDetail(null)} onToast={onToast}/>}</div>
}
function formatCustomerDate(value:string){return new Intl.DateTimeFormat("es-AR",{day:"2-digit",month:"short",year:"numeric"}).format(new Date(value.includes("T")?value:`${value}T12:00:00`))}
function CustomerModal({initial,update,onClose,onToast}:any){const [f,setF]=useState<any>({type:initial?.type||"persona",name:initial?.name||"",businessName:initial?.businessName||"",contactName:initial?.contactName||"",phone:initial?.phone||"",email:initial?.email||"",address:initial?.address||"",notes:initial?.notes||""});const isBusiness=f.type==="negocio";const save=()=>{if(!f.name.trim())return;const now=new Date().toISOString();const payload={...f,name:f.name.trim(),businessName:isBusiness?f.name.trim():(f.businessName||""),type:f.type||"persona"};update((d:AppData)=>({...d,customers:initial?d.customers.map((c:Customer)=>c.id===initial.id?{...c,...payload,updatedAt:now}:c):[{...payload,id:"cus_"+Date.now(),createdAt:now,updatedAt:now},...d.customers]}));onToast(initial?"Cliente actualizado":"Cliente creado");onClose()};return <Modal title={initial?"Editar cliente":"Nuevo cliente"} onClose={onClose} footer={<><Button variant="ghost" onClick={onClose}>Cancelar</Button><Button onClick={save}>Guardar</Button></>}><div className="space-y-4"><Select label="Tipo de cliente" value={f.type} onChange={(e:ChangeEvent<HTMLSelectElement>)=>setF({...f,type:e.target.value})}><option value="persona">Persona</option><option value="negocio">Negocio</option></Select>{isBusiness?<><Input label="Nombre del negocio" value={f.name} onChange={(e:ChangeEvent<HTMLInputElement>)=>setF({...f,name:e.target.value})}/><Input label="Nombre del contacto (opcional)" value={f.contactName} onChange={(e:ChangeEvent<HTMLInputElement>)=>setF({...f,contactName:e.target.value})}/></>:<Input label="Nombre y apellido" value={f.name} onChange={(e:ChangeEvent<HTMLInputElement>)=>setF({...f,name:e.target.value})}/>}<Input label="Teléfono" value={f.phone} onChange={(e:ChangeEvent<HTMLInputElement>)=>setF({...f,phone:e.target.value})}/><Input label="Email (opcional)" type="email" value={f.email} onChange={(e:ChangeEvent<HTMLInputElement>)=>setF({...f,email:e.target.value})}/><Input label="Dirección (opcional)" value={f.address} onChange={(e:ChangeEvent<HTMLInputElement>)=>setF({...f,address:e.target.value})}/><Textarea label="Notas (opcional)" value={f.notes} onChange={(e:ChangeEvent<HTMLTextAreaElement>)=>setF({...f,notes:e.target.value})}/></div></Modal>}
function CustomerDetail({customer,data,onClose,onEdit,onOrder}:{customer:Customer;data:AppData;onClose:()=>void;onEdit:()=>void;onOrder:(o:Order)=>void}){const orders=data.orders.filter((o:Order)=>o.customerId===customer.id).sort((a:Order,b:Order)=>((b.orderDate||b.createdAt).localeCompare(a.orderDate||a.createdAt)));const spent=orders.reduce((s:number,o:Order)=>s+o.total,0);const pending=orders.reduce((s:number,o:Order)=>s+o.balance,0);const last=orders[0];const displayName=customer.name||customer.businessName||"Cliente";return <Modal title="Ficha del cliente" onClose={onClose} footer={<div className="flex w-full justify-end gap-2"><Button variant="ghost" onClick={onClose}>Cerrar</Button><Button onClick={onEdit}><Pencil size={15}/> Editar cliente</Button></div>}><div className="space-y-6"><div><div className="flex flex-wrap items-center gap-2"><h2 className="serif text-2xl font-semibold">{displayName}</h2><span className="rounded-full border border-[var(--border)] px-2 py-1 text-[10px] font-semibold tracking-wide text-[var(--muted)]">{(customer.type||"persona").toUpperCase()}</span></div>{customer.type==="negocio"&&customer.contactName&&<div className="mt-1 text-sm text-[var(--muted)]">Contacto: {customer.contactName}</div>}<div className="mt-3 space-y-1 text-sm"><div>Teléfono: {customer.phone||"No informado"}</div><div>Email: {customer.email||"No informado"}</div><div>Dirección: {customer.address||"No informada"}</div></div></div><div><h3 className="serif text-lg font-semibold">Resumen</h3><div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4"><Stat label="Pedidos" value={orders.length} icon={ClipboardList}/><Stat label="Gastado" value={money(spent)} icon={WalletCards}/><Stat label="Pendiente" value={money(pending)} icon={TrendingUp}/><Stat label="Último pedido" value={last?formatCustomerDate(last.orderDate||last.createdAt):"—"} icon={ClipboardList}/></div></div><div><h3 className="serif text-lg font-semibold">Datos del cliente</h3><div className="mt-3 rounded-xl border border-[var(--border)] bg-[var(--bg)] p-4 text-sm space-y-2">{customer.type==="negocio"?<><div><span className="text-[var(--muted)]">Nombre del negocio:</span> {displayName}</div><div><span className="text-[var(--muted)]">Contacto:</span> {customer.contactName||"No informado"}</div></>:<div><span className="text-[var(--muted)]">Nombre y apellido:</span> {displayName}</div>}<div><span className="text-[var(--muted)]">Teléfono:</span> {customer.phone||"No informado"}</div><div><span className="text-[var(--muted)]">Email:</span> {customer.email||"No informado"}</div><div><span className="text-[var(--muted)]">Dirección:</span> {customer.address||"No informada"}</div></div></div><div><div className="flex items-center justify-between"><h3 className="serif text-lg font-semibold">Historial de pedidos</h3></div><div className="mt-3 space-y-2">{orders.length?orders.map((o:Order,index:number)=><button key={o.id} onClick={()=>onOrder(o)} className="w-full rounded-xl border border-[var(--border)] bg-[var(--bg)] p-3 text-left transition hover:border-[var(--primary)]"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="font-semibold">Pedido #{o.id.replace(/^ord_/,'')}</div><div className="mt-1 text-xs text-[var(--muted)]">{formatCustomerDate(o.orderDate||o.createdAt)}</div><div className="mt-1 truncate text-sm">{o.items.map(i=>`${i.quantity} × ${i.productName}`).join(", ")}</div></div><div className="shrink-0 text-right"><div className="font-semibold">{money(o.total)}</div><div className="mt-1 text-xs text-[var(--muted)]">{o.balance>0?`Pendiente ${money(o.balance)}`:"Pagado"}</div><div className="mt-2 text-xs font-semibold text-[var(--primary)]">Ver pedido →</div></div></div></button>):<EmptyState title="Sin pedidos todavía" text="Los pedidos asociados a este cliente aparecerán acá."/>}</div></div>{customer.notes&&<div><h3 className="serif text-lg font-semibold">Notas</h3><div className="mt-2 rounded-xl border border-[var(--border)] bg-[var(--bg)] p-4 text-sm text-[var(--muted)] whitespace-pre-wrap">{customer.notes}</div></div>}</div></Modal>}

export function Products({data,update,onToast,createIntent}:any){const [modal,setModal]=useState(false);useEffect(()=>{if(createIntent==="product"){setEditing(null);setModal(true)}},[createIntent]);const [editing,setEditing]=useState<Product|null>(null);const [detail,setDetail]=useState<Product|null>(null);return <div className="space-y-5"><PageHeader title="Productos / recetas" subtitle="Recetas, costos y precios de venta." action={<Button onClick={()=>{setEditing(null);setModal(true)}}><Plus size={17}/> Nueva receta</Button>}/>{data.products.length?<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.products.map((p:Product)=>{const cost=calculateRealCost(p,data.ingredients);const profit=p.price-cost;const margin=calculateMargin(p.price,cost);return <Card key={p.id} className="p-5"><div className="flex justify-between gap-3"><button className="min-w-0 text-left" onClick={()=>setDetail(p)}><div className="flex items-center gap-2"><CakeSlice size={18} className="text-[var(--primary)]"/><h3 className="truncate font-semibold">{p.name}</h3></div><p className="mt-1 line-clamp-2 text-sm text-[var(--muted)]">{p.description||"Sin descripción"}</p></button><div className="flex shrink-0 gap-1"><button aria-label="Editar receta" onClick={()=>{setEditing(p);setModal(true)}} className="rounded-lg p-2 hover:bg-[var(--bg)]"><Pencil size={17}/></button><button aria-label="Eliminar receta" onClick={()=>{if(confirm(`¿Eliminar la receta ${p.name}?`))update((d:AppData)=>({...d,products:d.products.filter(x=>x.id!==p.id)}));}} className="rounded-lg p-2 text-[var(--danger)] hover:bg-[var(--bg)]"><Trash2 size={17}/></button></div></div><div className="mt-5 grid grid-cols-2 gap-3 text-sm sm:grid-cols-4"><div><div className="text-xs text-[var(--muted)]">Costo</div><b>{money(cost)}</b></div><div><div className="text-xs text-[var(--muted)]">Precio</div><b>{money(p.price)}</b></div><div><div className="text-xs text-[var(--muted)]">Ganancia</div><b className={profit<0?"text-[var(--danger)]":""}>{money(profit)}</b></div><div><div className="text-xs text-[var(--muted)]">Margen</div><b className={profit<0?"text-[var(--danger)]":""}>{p.price?margin.toFixed(1)+"%":"—"}</b></div></div>{p.price>0&&profit<0&&<div className="mt-3 rounded-xl bg-[var(--danger)]/10 p-3 text-xs text-[var(--danger)]">El precio de venta está por debajo del costo.</div>}{p.ingredients.length===0&&<div className="mt-3 rounded-xl bg-[var(--warning)]/10 p-3 text-xs">Falta configurar la receta con insumos.</div>}<div className="mt-4 flex items-center justify-between rounded-xl bg-[var(--bg)] p-3 text-xs text-[var(--muted)]"><span>Ingredientes {p.ingredients.length} · Tiempo {p.laborHours} h</span><button onClick={()=>setDetail(p)} className="font-semibold text-[var(--primary)]">Ver receta →</button></div></Card>})}</div>:<Card><EmptyState title="Todavía no hay recetas" text="Creá una receta para empezar a calcular costos." action={<Button onClick={()=>setModal(true)}>Crear receta</Button>}/></Card>}{modal&&<ProductModal initial={editing} data={data} update={update} onClose={()=>setModal(false)} onToast={onToast}/>} {detail&&<ProductDetail product={detail} data={data} onClose={()=>setDetail(null)} onEdit={()=>{setEditing(detail);setDetail(null);setModal(true)}}/>}</div>}

function ProductModal({initial,data,update,onClose,onToast}:any){const empty={name:"",description:"",price:0,margin:40,ingredients:[],packaging:[],laborHours:0,laborRate:4000,variants:[],active:true};const [f,setF]=useState<any>(initial?{...initial,ingredients:[...(initial.ingredients||[])],packaging:[...(initial.packaging||[])]}:empty);const [newIngredient,setNewIngredient]=useState(false);const cost=calculateRealCost(f,data.ingredients);const ingredientCost=calculateIngredientCost(f,data.ingredients);const packagingCost=f.packaging.reduce((sum:number,x:any)=>{const i=x.ingredientId?data.ingredients.find((v:Ingredient)=>v.id===x.ingredientId):null;return sum+(i?calculateIngredientUnitCost(i)*toBaseQuantity(x.quantity,x.unit||i.baseUnit):x.cost||0)},0);const laborCost=f.laborHours*f.laborRate;const suggested=f.margin>0&&f.margin<100?calculateSuggestedPrice(cost,Number(f.margin)):0;const profit=Number(f.price)-cost;const realMargin=calculateMargin(Number(f.price),cost);const packagingIngredients=data.ingredients.filter((i:Ingredient)=>i.category.toLowerCase().includes("pack"));const addIngredient=()=>{const i=data.ingredients.find((x:Ingredient)=>!f.ingredients.some((r:any)=>r.ingredientId===x.id));if(i)setF({...f,ingredients:[...f.ingredients,{ingredientId:i.id,quantity:1,unit:i.baseUnit}]})};const addPackaging=()=>{const i=packagingIngredients.find((x:Ingredient)=>!f.packaging.some((r:any)=>r.ingredientId===x.id));if(i)setF({...f,packaging:[...f.packaging,{ingredientId:i.id,name:i.name,quantity:1,unit:i.baseUnit,cost:0}]});else setF({...f,packaging:[...f.packaging,{name:"",quantity:1,cost:0}]})};const save=()=>{if(!f.name.trim()){onToast("El nombre es obligatorio");return}if(Number(f.price)<0||Number(f.margin)<0||Number(f.margin)>=100||Number(f.laborHours)<0||Number(f.laborRate)<0){onToast("Revisá los valores ingresados");return}if(f.ingredients.some((x:any)=>!x.ingredientId||Number(x.quantity)<=0)){onToast("Cada ingrediente debe tener una cantidad mayor a 0");return}if(f.packaging.some((x:any)=>Number(x.quantity)<=0)){onToast("La cantidad del packaging debe ser mayor a 0");return}const now=new Date().toISOString();const item={...f,price:Number(f.price),margin:Number(f.margin),laborHours:Number(f.laborHours),laborRate:Number(f.laborRate),id:initial?.id||"prod_"+Date.now(),createdAt:initial?.createdAt||now,updatedAt:now};update((d:AppData)=>({...d,products:initial?d.products.map(p=>p.id===initial.id?item:p):[item,...d.products]}));onToast(initial?"Receta actualizada":"Receta creada");onClose()};return <><Modal title={initial?"Editar receta":"Nueva receta"} onClose={onClose} footer={<><Button variant="ghost" onClick={onClose}>Cancelar</Button><Button onClick={save}>Guardar receta</Button></>}><div className="space-y-5"><Section title="Información"><div className="space-y-3"><Input label="Nombre" value={f.name} onChange={(e:any)=>setF({...f,name:e.target.value})}/><Input label="Descripción" value={f.description} onChange={(e:any)=>setF({...f,description:e.target.value})}/><div className="grid grid-cols-2 gap-3"><Input label="Precio de venta" type="number" min="0" value={f.price} onChange={(e:any)=>setF({...f,price:Number(e.target.value)})}/><Input label="Margen objetivo %" type="number" min="0" max="99.99" value={f.margin} onChange={(e:any)=>setF({...f,margin:Number(e.target.value)})}/></div></div></Section><Section title="Ingredientes" action={<div className="flex flex-wrap gap-2"><Button variant="ghost" onClick={()=>setNewIngredient(true)}><Plus size={15}/> Crear insumo</Button><Button variant="ghost" onClick={addIngredient} disabled={!data.ingredients.length}><Plus size={15}/> Agregar insumo</Button></div>}/><div className="space-y-2">{f.ingredients.length?f.ingredients.map((row:any,index:number)=>{const i=data.ingredients.find((x:Ingredient)=>x.id===row.ingredientId);const unitCost=i?calculateIngredientUnitCost(i):0;const rowCost=i?unitCost*toBaseQuantity(Number(row.quantity),row.unit||i.baseUnit):0;return <div key={index} className="grid gap-2 rounded-xl border border-[var(--border)] bg-[var(--bg)] p-3 sm:grid-cols-[minmax(0,1fr)_120px_80px_auto]"><Select label="Insumo" value={row.ingredientId} onChange={(e:ChangeEvent<HTMLSelectElement>)=>{const ni=data.ingredients.find((x:Ingredient)=>x.id===e.target.value);setF({...f,ingredients:f.ingredients.map((r:any,n:number)=>n===index?{...r,ingredientId:e.target.value,unit:ni?.baseUnit||r.unit}:r)})}}>{data.ingredients.map((x:Ingredient)=><option key={x.id} value={x.id}>{x.name}</option>)}</Select><Input label="Cantidad" type="number" min="0.001" step="0.001" value={row.quantity} onChange={(e:any)=>setF({...f,ingredients:f.ingredients.map((r:any,n:number)=>n===index?{...r,quantity:Number(e.target.value)}:r)})}/><Select label="Unidad" value={row.unit||i?.baseUnit||""} disabled={!i} onChange={(e:ChangeEvent<HTMLSelectElement>)=>setF({...f,ingredients:f.ingredients.map((r:any,n:number)=>n===index?{...r,unit:e.target.value}:r)})}>{i?compatibleUnits(i.baseUnit).map((u:Ingredient["baseUnit"])=> <option key={u} value={u}>{u}</option>):<option value="">—</option>}</Select><div className="flex items-center justify-between gap-2 pt-6"><b>{money(rowCost)}</b><button aria-label="Eliminar insumo" onClick={()=>setF({...f,ingredients:f.ingredients.filter((_:any,n:number)=>n!==index)})} className="text-[var(--danger)]"><Trash2 size={16}/></button></div></div>}) : <Card className="bg-[var(--bg)] p-4 text-sm text-[var(--muted)]">Todavía no agregaste insumos a esta receta.</Card>}</div>{!data.ingredients.length&&<div className="text-xs text-[var(--muted)]">Primero cargá insumos desde la sección Insumos.</div>}<Section title="Packaging" action={<Button variant="ghost" onClick={addPackaging}><Plus size={15}/> Agregar packaging</Button>}/><div className="space-y-2">{f.packaging.map((row:any,index:number)=>{const i=row.ingredientId?data.ingredients.find((x:Ingredient)=>x.id===row.ingredientId):null;const rowCost=i?calculateIngredientUnitCost(i)*toBaseQuantity(Number(row.quantity),row.unit||i.baseUnit):Number(row.cost)||0;return <div key={index} className="grid gap-2 rounded-xl border border-[var(--border)] bg-[var(--bg)] p-3 sm:grid-cols-[minmax(0,1fr)_120px_auto]">{packagingIngredients.length?<Select label="Elemento" value={row.ingredientId||""} onChange={(e:ChangeEvent<HTMLSelectElement>)=>{const ni=packagingIngredients.find((x:Ingredient)=>x.id===e.target.value);setF({...f,packaging:f.packaging.map((r:any,n:number)=>n===index?{...r,ingredientId:e.target.value,name:ni?.name||"",unit:ni?.baseUnit||r.unit,cost:0}:r)})}}><option value="">Seleccionar packaging</option>{packagingIngredients.map((x:Ingredient)=><option key={x.id} value={x.id}>{x.name}</option>)}</Select>:<Input label="Elemento" value={row.name||""} onChange={(e:any)=>setF({...f,packaging:f.packaging.map((r:any,n:number)=>n===index?{...r,name:e.target.value}:r)})}/>}<Input label="Cantidad" type="number" min="0.001" step="0.001" value={row.quantity} onChange={(e:any)=>setF({...f,packaging:f.packaging.map((r:any,n:number)=>n===index?{...r,quantity:Number(e.target.value)}:r)})}/><div className="flex items-center justify-between gap-2 pt-6"><div className="flex items-center gap-2"><Select label="Unidad" value={row.unit||i?.baseUnit||"unidad"} disabled={!i} onChange={(e:ChangeEvent<HTMLSelectElement>)=>setF({...f,packaging:f.packaging.map((r:any,n:number)=>n===index?{...r,unit:e.target.value}:r)})}>{i?compatibleUnits(i.baseUnit).map((u:Ingredient["baseUnit"])=> <option key={u} value={u}>{u}</option>):<option value="unidad">unidad</option>}</Select><b className="pt-6">{money(rowCost)}</b></div><button aria-label="Eliminar packaging" onClick={()=>setF({...f,packaging:f.packaging.filter((_:any,n:number)=>n!==index)})} className="text-[var(--danger)]"><Trash2 size={16}/></button></div></div>})}</div><Section title="Mano de obra"><div className="grid grid-cols-2 gap-3"><Input label="Horas de trabajo" type="number" min="0" step="0.5" value={f.laborHours} onChange={(e:any)=>setF({...f,laborHours:Number(e.target.value)})}/><Input label="Valor hora" type="number" min="0" value={f.laborRate} onChange={(e:any)=>setF({...f,laborRate:Number(e.target.value)})}/></div></Section><Card className="bg-[var(--bg)] p-4"><h3 className="font-semibold">Resumen de costos</h3><div className="mt-3 space-y-2 text-sm"><Row label="Ingredientes" value={money(ingredientCost)}/><Row label="Packaging" value={money(packagingCost)}/><Row label="Mano de obra" value={money(laborCost)}/><div className="border-t border-[var(--border)] pt-2"><Row label="Costo total" value={money(cost)} strong/></div><Row label="Precio sugerido" value={suggested?money(suggested):"—"}/><Row label="Precio de venta actual" value={f.price>0?money(f.price):"Sin definir"}/><Row label="Ganancia" value={f.price>0?money(profit):"Falta precio de venta"}/><Row label="Margen real" value={f.price>0?realMargin.toFixed(2)+"%":"—"}/></div>{f.price>0&&profit<0&&<div className="mt-3 rounded-xl bg-[var(--danger)]/10 p-3 text-sm text-[var(--danger)]">Hay una pérdida de {money(Math.abs(profit))}: el precio de venta es menor que el costo.</div>}{!f.ingredients.length&&<div className="mt-3 rounded-xl bg-[var(--warning)]/10 p-3 text-sm">Falta configurar la receta con ingredientes.</div>}</Card></div></Modal>{newIngredient&&<IngredientModal initial={null} update={update} onClose={()=>setNewIngredient(false)} onToast={onToast} onSaved={(item:any)=>{setF((current:any)=>({...current,ingredients:[...current.ingredients,{ingredientId:item.id,quantity:1,unit:item.baseUnit}]}));setNewIngredient(false)}}/>}</>}

function ProductDetail({product,data,onClose,onEdit}:{product:Product;data:AppData;onClose:()=>void;onEdit:()=>void}){const cost=calculateRealCost(product,data.ingredients);const suggested=product.margin>0&&product.margin<100?calculateSuggestedPrice(cost,product.margin):0;return <Modal title="Ver receta" onClose={onClose} footer={<div className="flex w-full justify-end gap-2"><Button variant="ghost" onClick={onClose}>Cerrar</Button><Button onClick={onEdit}><Pencil size={15}/> Editar receta</Button></div>}><div className="space-y-5"><div><h2 className="serif text-2xl font-semibold">{product.name}</h2><p className="mt-1 text-sm text-[var(--muted)]">{product.description||"Sin descripción"}</p></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4"><Stat label="Costo" value={money(cost)} icon={CakeSlice}/><Stat label="Precio" value={product.price?money(product.price):"—"} icon={WalletCards}/><Stat label="Ganancia" value={product.price?money(product.price-cost):"—"} icon={TrendingUp}/><Stat label="Margen" value={product.price?calculateMargin(product.price,cost).toFixed(1)+"%":"—"} icon={ChartNoAxesCombined}/></div><Section title="Ingredientes"><div className="space-y-2">{product.ingredients.length?product.ingredients.map((row:any,index:number)=>{const i=data.ingredients.find((x:Ingredient)=>x.id===row.ingredientId);const rowCost=i?calculateIngredientUnitCost(i)*toBaseQuantity(row.quantity,row.unit||i.baseUnit):0;return <div key={index} className="flex items-center justify-between rounded-xl bg-[var(--bg)] p-3 text-sm"><span>{i?.name||"Insumo eliminado"} · {row.quantity} {row.unit||i?.baseUnit}</span><b>{money(rowCost)}</b></div>}):<div className="text-sm text-[var(--muted)]">Sin ingredientes configurados.</div>}</div></Section><Section title="Packaging"><div className="space-y-2">{product.packaging.length?product.packaging.map((row:any,index:number)=>{const i=row.ingredientId?data.ingredients.find((x:Ingredient)=>x.id===row.ingredientId):null;const rowCost=i?calculateIngredientUnitCost(i)*toBaseQuantity(row.quantity,row.unit||i.baseUnit):row.cost||0;return <div key={index} className="flex items-center justify-between rounded-xl bg-[var(--bg)] p-3 text-sm"><span>{i?.name||row.name||"Packaging"} · {row.quantity} {row.unit||i?.baseUnit||"unidad"}</span><b>{money(rowCost)}</b></div>}):<div className="text-sm text-[var(--muted)]">Sin packaging configurado.</div>}</div></Section><Section title="Precio sugerido"><div className="rounded-xl bg-[var(--bg)] p-4 text-sm">Con un margen objetivo del {product.margin}%, el precio sugerido es <b>{suggested?money(suggested):"—"}</b>.</div></Section></div></Modal>}

export function Ingredients({data,update,onToast,createIntent}:any){const [modal,setModal]=useState(false);useEffect(()=>{if(createIntent==="ingredient")setModal(true)},[createIntent]);const [editing,setEditing]=useState<Ingredient|null>(null);return <div className="space-y-5"><PageHeader title="Insumos" subtitle="Precios de compra y stock actual." action={<Button onClick={()=>{setEditing(null);setModal(true)}}><Plus size={17}/> Nuevo insumo</Button>}/><div className="grid gap-3 sm:grid-cols-2">{data.ingredients.map((i:Ingredient)=><Card key={i.id} className="p-4"><div className="flex justify-between"><div><div className="font-semibold">{i.name}</div><div className="text-xs text-[var(--muted)]">{i.category} · {money(i.purchasePrice)}</div></div><button onClick={()=>{setEditing(i);setModal(true)}}><Pencil size={17}/></button></div><div className="mt-4 h-2 overflow-hidden rounded-full bg-[var(--bg)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{width:`${Math.min(100,(i.stock/Math.max(i.minimumStock*2,1))*100)}%`}}/></div><div className="mt-2 flex justify-between text-xs"><span>{i.stock} {i.baseUnit}</span>{i.stock<=i.minimumStock?<Badge tone="warning">Stock bajo</Badge>:<Badge tone="success">Suficiente</Badge>}</div></Card>)}</div>{modal&&<IngredientModal initial={editing} update={update} onClose={()=>setModal(false)} onToast={onToast}/>}</div>}
function IngredientModal({initial,update,onClose,onToast,onSaved}:any){const [f,setF]=useState<any>(initial||{name:"",category:"",purchaseUnit:"unidad",purchaseQuantity:1000,baseUnit:"g",purchasePrice:0,stock:0,minimumStock:1000});const save=()=>{if(!f.name.trim()){onToast("El nombre del insumo es obligatorio");return}const now=new Date().toISOString();const item={...f,id:initial?.id||"ing_"+Date.now(),createdAt:initial?.createdAt||now,updatedAt:now};update((d:AppData)=>({...d,ingredients:initial?d.ingredients.map(i=>i.id===initial.id?item:i):[item,...d.ingredients]}));onToast(initial?"Insumo actualizado":"Insumo agregado correctamente");onSaved?.(item);if(!onSaved)onClose()};return <Modal title={initial?"Editar insumo":"Nuevo insumo"} onClose={onClose} footer={<><Button variant="ghost" onClick={onClose}>Cancelar</Button><Button onClick={save}>Guardar</Button></>}><div className="space-y-4"><Input label="Nombre" value={f.name} onChange={(e:any)=>setF({...f,name:e.target.value})}/><Input label="Categoría" value={f.category} onChange={(e:any)=>setF({...f,category:e.target.value})}/><div className="grid grid-cols-2 gap-4"><Input label="Cantidad de compra" type="number" min="0" value={f.purchaseQuantity} onChange={(e:any)=>setF({...f,purchaseQuantity:Number(e.target.value)})}/><Select label="Unidad de compra" value={f.purchaseUnit} onChange={(e:any)=>setF({...f,purchaseUnit:e.target.value})}><option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="l">l</option><option value="unidad">unidad</option></Select></div><div className="grid grid-cols-2 gap-4"><Input label="Precio de compra" type="number" min="0" value={f.purchasePrice} onChange={(e:any)=>setF({...f,purchasePrice:Number(e.target.value)})}/><Select label="Unidad base" value={f.baseUnit} onChange={(e:any)=>setF({...f,baseUnit:e.target.value})}><option value="g">g</option><option value="kg">kg</option><option value="ml">ml</option><option value="l">l</option><option value="unidad">unidad</option></Select></div><div className="grid grid-cols-2 gap-4"><Input label="Stock actual" type="number" min="0" value={f.stock} onChange={(e:any)=>setF({...f,stock:Number(e.target.value)})}/><Input label="Stock mínimo" type="number" min="0" value={f.minimumStock} onChange={(e:any)=>setF({...f,minimumStock:Number(e.target.value)})}/></div></div></Modal>}

export function Inventory({data,update,onToast}:any){const [modal,setModal]=useState(false);const [editing,setEditing]=useState<Ingredient|null>(null);const low=data.ingredients.filter((i:Ingredient)=>i.stock<=i.minimumStock);return <div className="space-y-5"><PageHeader title="Inventario" subtitle="Stock actual y necesidades de reposición." action={<Button onClick={()=>{setEditing(null);setModal(true)}}><Plus size={17}/> Nuevo insumo</Button>}/>{low.length>0&&<div className="grid gap-2 sm:grid-cols-2">{low.map((i:Ingredient)=><StockAlert key={i.id} name={i.name} stock={i.stock} unit={i.baseUnit}/>)}</div>}<div className="grid gap-3">{data.ingredients.map((i:Ingredient)=><Card key={i.id} className="p-4"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><div className="rounded-xl bg-[var(--bg)] p-2"><Package size={18} className="text-[var(--primary)]"/></div><div><div className="font-semibold">{i.name}</div><div className="text-xs text-[var(--muted)]">Mínimo {i.minimumStock} {i.baseUnit}</div></div></div><div className="text-right"><div className="font-bold">{i.stock} {i.baseUnit}</div><div className="text-xs text-[var(--muted)]">{i.stock<=i.minimumStock?"Stock bajo":"Stock suficiente"}</div></div></div></Card>)}</div>{modal&&<IngredientModal initial={editing} update={update} onClose={()=>setModal(false)} onToast={onToast}/>}</div>}

function Row({label,value,strong=false}:{label:string;value:string;strong?:boolean}){return <div className={"flex items-center justify-between gap-4 "+(strong?"font-semibold":"")}><span className={strong?"text-[var(--text)]":"text-[var(--muted)]"}>{label}</span><span>{value}</span></div>}


const expenseCategories=["Ingredientes","Packaging","Delivery / Envíos","Publicidad","Servicios","Equipamiento","Alquiler","Comisiones","Otros"] as const;
type ExpenseCategory=typeof expenseCategories[number];
function expenseDate(value:string){return new Intl.DateTimeFormat("es-AR",{day:"2-digit",month:"2-digit",year:"numeric"}).format(new Date(`${value}T12:00:00`))}
function periodRange(period:string,reference=new Date()){const start=new Date(reference);const end=new Date(reference);if(period==="today"){start.setHours(0,0,0,0);end.setHours(23,59,59,999)}else if(period==="yesterday"){start.setDate(start.getDate()-1);start.setHours(0,0,0,0);end.setDate(end.getDate()-1);end.setHours(23,59,59,999)}else if(period==="week"){start.setDate(start.getDate()-6);start.setHours(0,0,0,0);end.setHours(23,59,59,999)}else{start.setDate(1);start.setHours(0,0,0,0);end.setHours(23,59,59,999)}return {start,end}}
function dateInRange(value:string,range:{start:Date;end:Date}){const d=new Date(`${value.slice(0,10)}T12:00:00`);return d>=range.start&&d<=range.end}
function previousPeriod(period:string){const now=new Date();const current=periodRange(period,now);const duration=current.end.getTime()-current.start.getTime()+1;return {start:new Date(current.start.getTime()-duration),end:new Date(current.start.getTime()-1)}}
function percentChange(current:number,previous:number){return previous?((current-previous)/previous)*100:null}
function ChangeLabel({current,previous}:{current:number;previous:number}){const change=percentChange(current,previous);if(change===null)return null;const sign=change>0?"↑":change<0?"↓":"→";return <div className="mt-1 text-xs text-[var(--muted)]">{sign} {Math.abs(change).toFixed(0)}% vs período anterior</div>}
function ExpenseModal({initial,onClose,onSave}:{initial:Expense|null;onClose:()=>void;onSave:(expense:Expense)=>void}){const [f,setF]=useState({description:initial?.description||"",amount:initial?.amount?String(initial.amount):"",category:initial?.category||"Otros",date:initial?.date||today(),note:initial?.note||""});const [error,setError]=useState("");const save=()=>{const amount=Number(f.amount);if(!f.description.trim())return setError("Ingresá un concepto para el gasto.");if(!Number.isFinite(amount)||amount<=0)return setError("El monto debe ser mayor a 0.");if(!f.date)return setError("Seleccioná una fecha.");onSave({id:initial?.id||`exp_${Date.now()}`,description:f.description.trim(),amount,category:f.category,date:f.date,note:f.note.trim()});onClose()};return <Modal title={initial?"Editar gasto":"Agregar gasto"} onClose={onClose} footer={<><Button variant="ghost" onClick={onClose}>Cancelar</Button><Button onClick={save}>Guardar gasto</Button></>}>{error&&<div className="rounded-xl border border-[var(--danger)]/30 bg-[var(--danger)]/10 p-3 text-sm text-[var(--danger)]">{error}</div>}<div className="space-y-4"><Input label="Concepto" value={f.description} onChange={(e:ChangeEvent<HTMLInputElement>)=>{setF({...f,description:e.target.value});setError("")}} placeholder="Ej. Harina y chocolate"/><Input label="Monto" type="number" min="0" value={f.amount} onChange={(e:ChangeEvent<HTMLInputElement>)=>{setF({...f,amount:e.target.value});setError("")}} placeholder="0"/><Select label="Categoría" value={f.category} onChange={(e:ChangeEvent<HTMLSelectElement>)=>setF({...f,category:e.target.value})}>{expenseCategories.map(c=><option key={c} value={c}>{c}</option>)}</Select><Input label="Fecha" type="date" value={f.date} onChange={(e:ChangeEvent<HTMLInputElement>)=>setF({...f,date:e.target.value})}/><Textarea label="Nota (opcional)" value={f.note} onChange={(e:ChangeEvent<HTMLTextAreaElement>)=>setF({...f,note:e.target.value})} placeholder="Detalle adicional"/></div></Modal>}
function ExpenseListModal({expenses,onClose,onEdit,onDelete}:{expenses:Expense[];onClose:()=>void;onEdit:(e:Expense)=>void;onDelete:(e:Expense)=>void}){return <Modal title="Gastos del período" onClose={onClose}><div className="space-y-2">{expenses.length?expenses.map(e=><div key={e.id} className="rounded-xl border border-[var(--border)] bg-[var(--bg)] p-3"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="font-semibold">{e.description}</div><div className="mt-1 text-xs text-[var(--muted)]">{e.category} · {expenseDate(e.date)}</div>{e.note&&<div className="mt-1 text-xs text-[var(--muted)]">{e.note}</div>}</div><b className="shrink-0">{money(e.amount)}</b></div><div className="mt-3 flex justify-end gap-2"><Button variant="ghost" onClick={()=>onEdit(e)}><Pencil size={14}/> Editar</Button><Button variant="ghost" onClick={()=>onDelete(e)}><Trash2 size={14}/> Eliminar</Button></div></div>):<EmptyState title="No tenés gastos registrados todavía." text="Agregá un gasto real para empezar a medir tus números."/>}</div></Modal>}
function PendingOrdersModal({orders,onClose}:{orders:Order[];onClose:()=>void}){return <Modal title="Pendiente de cobro" onClose={onClose}><div className="space-y-2">{orders.length?orders.map(o=><div key={o.id} className="rounded-xl border border-[var(--border)] bg-[var(--bg)] p-3"><div className="flex justify-between gap-3"><div><div className="font-semibold">Pedido #{o.id.replace(/^ord_/,'')}</div><div className="text-xs text-[var(--muted)]">{o.items.map(i=>`${i.quantity} × ${i.productName}`).join(", ")}</div></div><div className="text-right"><div className="font-semibold">{money(o.balance)}</div><div className="text-xs text-[var(--muted)]">Pendiente</div></div></div></div>):<EmptyState title="No hay cobros pendientes" text="Los pedidos con saldo pendiente aparecerán acá."/>}</div></Modal>}
function SalesTrendChart({points}:{points:{key:string;sales:number;ingredients:number;after:number}[]}){
 const [hovered,setHovered]=useState<number|null>(null);
 const width=800, height=280, padX=28, padTop=18, padBottom=34, plotW=width-padX*2, plotH=height-padTop-padBottom;
 const maxValue=Math.max(...points.map(p=>p.sales),1);
 const y=(value:number)=>padTop+plotH-(value/maxValue)*plotH;
 const x=(index:number)=>padX+(points.length===1?plotW/2:(index/(points.length-1))*plotW);
 const line=points.map((p,i)=>`${x(i).toFixed(1)},${y(p.sales).toFixed(1)}`).join(' ');
 const area=`${padX},${padTop+plotH} ${line} ${padX+plotW},${padTop+plotH}`;
 const gridValues=[maxValue,maxValue/2,0];
 const labelStep=Math.max(1,Math.ceil(points.length/6));
 const formatDate=(key:string)=>new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short'}).format(new Date(`${key}T12:00:00`)).replace('.','');
 const formatLongDate=(key:string)=>new Intl.DateTimeFormat('es-AR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${key}T12:00:00`));
 const handleMove=(event:any)=>{
   if(!points.length)return;
   const rect=event.currentTarget.getBoundingClientRect();
   const relative=Math.max(0,Math.min(rect.width,event.clientX-rect.left));
   const index=points.length===1?0:Math.round((relative/rect.width)*(points.length-1));
   setHovered(index);
 };
 const active=hovered===null?null:points[hovered];
 return <div className="mt-5 rounded-2xl border border-[var(--border)] bg-[var(--bg)] p-3 sm:p-4">
   {!points.length?<div className="flex h-64 items-center justify-center text-sm text-[var(--muted)]">Todavía no hay ventas para mostrar en este período.</div>:<>
     <div className="relative h-64 w-full">
       <svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" className="h-full w-full" onMouseMove={handleMove} onMouseLeave={()=>setHovered(null)} onTouchMove={(e:any)=>handleMove(e.touches[0])} role="img" aria-label="Evolución de ventas">
         {gridValues.map((value,i)=>{const gy=y(value);return <g key={i}><line x1={padX} x2={padX+plotW} y1={gy} y2={gy} stroke="currentColor" strokeOpacity={i===2?0.18:0.08} strokeWidth="1"/><text x="0" y={gy+4} fontSize="11" fill="currentColor" opacity="0.58">{i===2?'$0':money(value)}</text></g>})}
         <polygon points={area} fill="var(--primary)" fillOpacity="0.09"/>
         <polyline points={line} fill="none" stroke="var(--primary)" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" vectorEffect="non-scaling-stroke"/>
         {points.map((p,i)=><circle key={p.key} cx={x(i)} cy={y(p.sales)} r={hovered===i?5:2.5} fill="var(--surface)" stroke="var(--primary)" strokeWidth="2" vectorEffect="non-scaling-stroke" className="transition-all"/>)}
         {hovered!==null&&<line x1={x(hovered)} x2={x(hovered)} y1={padTop} y2={padTop+plotH} stroke="currentColor" strokeOpacity="0.14" strokeDasharray="4 4" vectorEffect="non-scaling-stroke"/>}
       </svg>
       {active&&<div className="pointer-events-none absolute left-1/2 top-3 z-10 w-52 -translate-x-1/2 rounded-xl border border-[var(--border)] bg-[var(--surface)] p-3 shadow-lg sm:left-auto sm:right-3 sm:translate-x-0">
         <div className="text-xs font-semibold">{formatLongDate(active.key)}</div>
         <div className="mt-2 space-y-1 text-xs"><div className="flex justify-between gap-3"><span className="text-[var(--muted)]">Ventas</span><b>{money(active.sales)}</b></div><div className="flex justify-between gap-3"><span className="text-[var(--muted)]">Insumos</span><b>{money(active.ingredients)}</b></div><div className="flex justify-between gap-3"><span className="text-[var(--muted)]">Después de insumos</span><b>{money(active.after)}</b></div></div>
       </div>}
     </div>
     <div className="mt-1 flex justify-between gap-2 px-7 text-[10px] text-[var(--muted)]">{points.map((p,i)=>i%labelStep===0||i===points.length-1?<span key={p.key}>{formatDate(p.key)}</span>:<span key={p.key} aria-hidden="true"/> )}</div>
   </>}
 </div>
}

export function Statistics({data,update,onToast,onBack,createIntent}:{data:AppData;update:(m:(d:AppData)=>AppData)=>void;onToast:(s:string)=>void;onBack:()=>void;createIntent?:"order"|"customer"|"ingredient"|"product"|"expense"|null}){
 const [period,setPeriod]=useState('month');
 const [chartPeriod,setChartPeriod]=useState<'7d'|'30d'|'3m'|'1y'>('30d');
 const [expenseModal,setExpenseModal]=useState<Expense|null|'new'>(null);
 const [expenseList,setExpenseList]=useState(false);
 const [pendingList,setPendingList]=useState(false);
 useEffect(()=>{if(createIntent==="expense")setExpenseModal("new")},[createIntent]);
 const now=new Date();
 const metricDate=(o:Order)=>o.orderDate||o.createdAt.slice(0,10);
 const range=useMemo(()=>periodRange(period,now),[period]);
 const prevRange=useMemo(()=>previousPeriod(period),[period]);
 const inPeriodOrder=(o:Order)=>{const d=new Date(`${metricDate(o)}T12:00:00`);return d>=range.start&&d<=range.end&&o.status!=='Cancelado'};
 const orders=data.orders.filter(inPeriodOrder);
 const periodExpenses=data.expenses.filter(e=>dateInRange(e.date,range));
 const previousOrders=data.orders.filter(o=>{const d=new Date(`${metricDate(o)}T12:00:00`);return d>=prevRange.start&&d<=prevRange.end&&o.status!=='Cancelado'});
 const previousExpenses=data.expenses.filter(e=>dateInRange(e.date,prevRange));
 const sales=orders.reduce((s,o)=>s+o.total,0);
 const ingredientCosts=orders.reduce((s,o)=>s+calculateOrderIngredientCost(o,data.products,data.ingredients),0);
 const netAfterIngredients=sales-ingredientCosts;
 const afterIngredientsMargin=sales>0?(netAfterIngredients/sales)*100:0;
 const previousSales=previousOrders.reduce((s,o)=>s+o.total,0);
 const previousIngredientCosts=previousOrders.reduce((s,o)=>s+calculateOrderIngredientCost(o,data.products,data.ingredients),0);
 const expenses=periodExpenses.reduce((s,e)=>s+e.amount,0);
 const previousExpenseTotal=previousExpenses.reduce((s,e)=>s+e.amount,0);
 const avg=orders.length?sales/orders.length:0;
 const productCounts=orders.flatMap(o=>o.items).reduce((a:any,i:any)=>(a[i.productName]=(a[i.productName]||0)+i.quantity,a),{});
 const productSales=orders.flatMap(o=>o.items).reduce((a:any,i:any)=>{a[i.productName]=(a[i.productName]||0)+i.subtotal;return a},{});
 const top=Object.entries(productCounts).sort((a:any,b:any)=>(b[1] as number)-(a[1] as number)).slice(0,5);
 const max=Math.max(...top.map(x=>x[1] as number),1);
 const categoryTotals=periodExpenses.reduce((a:any,e)=>{a[e.category]=(a[e.category]||0)+e.amount;return a},{});
 const categories=Object.entries(categoryTotals).sort((a:any,b)=>(b[1] as number)-(a[1] as number));
 const pendingOrders=orders.filter(o=>o.balance>0);
 const pendingTotal=pendingOrders.reduce((s,o)=>s+o.balance,0);
 const chartPoints=useMemo(()=>{
   const end=new Date(now);end.setHours(23,59,59,999);
   const start=new Date(end);
   if(chartPeriod==='7d')start.setDate(start.getDate()-6);
   else if(chartPeriod==='30d')start.setDate(start.getDate()-29);
   else if(chartPeriod==='3m'){start.setDate(1);start.setMonth(start.getMonth()-2);}
   else{start.setDate(1);start.setMonth(start.getMonth()-11);}
   start.setHours(0,0,0,0);
   const days=Math.max(1,Math.ceil((end.getTime()-start.getTime())/86400000)+1);
   return Array.from({length:days},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const key=d.toISOString().slice(0,10);const dayOrders=data.orders.filter(o=>metricDate(o)===key&&o.status!=='Cancelado');const daySales=dayOrders.reduce((s,o)=>s+o.total,0);const dayIngredients=dayOrders.reduce((s,o)=>s+calculateOrderIngredientCost(o,data.products,data.ingredients),0);return {key,sales:daySales,ingredients:dayIngredients,after:daySales-dayIngredients};});
 },[chartPeriod,data.orders,data.products,data.ingredients]);
 const chartPointsVisible=chartPoints.some(p=>p.sales>0)?chartPoints:[];
 const saveExpense=(expense:Expense)=>{update(d=>({...d,expenses:d.expenses.some(e=>e.id===expense.id)?d.expenses.map(e=>e.id===expense.id?expense:e):[expense,...d.expenses]}));onToast(expenseModal&&expenseModal!=='new'?'Gasto actualizado':'Gasto registrado');setExpenseModal(null)};
 const deleteExpense=(expense:Expense)=>{if(!window.confirm(`¿Eliminar el gasto "${expense.description}"?`))return;update(d=>({...d,expenses:d.expenses.filter(e=>e.id!==expense.id)}));onToast('Gasto eliminado')};
 return <div className="space-y-5">
   <PageHeader title="Estadísticas" subtitle="Tus números reales, claros y fáciles de entender." back onBack={onBack}/>
   <div className="flex gap-2 overflow-auto pb-1">{[['today','Hoy'],['yesterday','Ayer'],['week','Esta semana'],['month','Este mes']].map(([id,label])=><button key={id} onClick={()=>setPeriod(id)} className={`whitespace-nowrap rounded-full border px-3 py-2 text-xs ${period===id?'border-[var(--primary)] bg-[var(--primary)] text-white':'border-[var(--border)]'}`}>{label}</button>)}</div>
   <Card className="overflow-hidden p-5 sm:p-6">
     <div className="flex flex-col gap-5">
       <div><div className="text-xs font-medium text-[var(--muted)]">Ventas del período</div><div className="mt-1 text-sm text-[var(--muted)]">El resultado principal después de cubrir los insumos.</div></div>
       <div><div className="text-sm font-medium text-[var(--muted)]">Después de insumos</div><div className="mt-1 text-3xl font-bold tracking-tight sm:text-4xl">{money(netAfterIngredients)}</div></div>
       <div className="grid grid-cols-2 gap-3 sm:max-w-md"><div className="rounded-xl bg-[var(--bg)] p-3"><div className="text-xs text-[var(--muted)]">Ventas</div><div className="mt-1 text-lg font-semibold">{money(sales)}</div></div><div className="rounded-xl bg-[var(--bg)] p-3"><div className="text-xs text-[var(--muted)]">Insumos</div><div className="mt-1 text-lg font-semibold">{money(ingredientCosts)}</div></div></div>
     </div>
     <div className="mt-6 flex items-center justify-between gap-3"><div><h2 className="serif text-xl font-semibold">Evolución de ventas</h2><p className="mt-1 text-xs text-[var(--muted)]">Ventas reales registradas por día.</p></div><div className="flex shrink-0 gap-1 rounded-xl border border-[var(--border)] bg-[var(--bg)] p-1">{[['7d','7 días'],['30d','30 días'],['3m','3 meses'],['1y','1 año']].map(([id,label])=><button key={id} onClick={()=>setChartPeriod(id as any)} className={`rounded-lg px-2 py-1.5 text-[10px] font-semibold sm:px-3 ${chartPeriod===id?'bg-[var(--primary)] text-white':'text-[var(--muted)] hover:text-[var(--text)]'}`}>{label}</button>)}</div></div>
     <SalesTrendChart points={chartPointsVisible}/>
     <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-5"><div className="rounded-xl bg-[var(--bg)] p-3"><div className="text-[10px] uppercase tracking-wide text-[var(--muted)]">Ventas</div><div className="mt-1 font-semibold">{money(sales)}</div></div><div className="rounded-xl bg-[var(--bg)] p-3"><div className="text-[10px] uppercase tracking-wide text-[var(--muted)]">Insumos</div><div className="mt-1 font-semibold">{money(ingredientCosts)}</div></div><div className="rounded-xl bg-[var(--bg)] p-3"><div className="text-[10px] uppercase tracking-wide text-[var(--muted)]">Después de insumos</div><div className="mt-1 font-semibold">{money(netAfterIngredients)}</div></div><div className="rounded-xl bg-[var(--bg)] p-3"><div className="text-[10px] uppercase tracking-wide text-[var(--muted)]">Margen</div><div className="mt-1 font-semibold">{sales?`${afterIngredientsMargin.toFixed(1)}%`:'—'}</div></div><div className="rounded-xl bg-[var(--bg)] p-3"><div className="text-[10px] uppercase tracking-wide text-[var(--muted)]">Pedidos</div><div className="mt-1 font-semibold">{orders.length}</div></div></div>
   </Card>
   {(previousSales>0&&sales>0)||(previousExpenseTotal>0&&expenses>0)?<Card className="p-5"><h2 className="serif text-xl font-semibold">Comparación</h2><div className="mt-4 grid gap-3 sm:grid-cols-2">{previousSales>0&&sales>0&&<div className="rounded-xl bg-[var(--bg)] p-4"><div className="text-xs text-[var(--muted)]">Ventas</div><div className="mt-1 text-lg font-bold">{money(sales)}</div><ChangeLabel current={sales} previous={previousSales}/></div>}{previousExpenseTotal>0&&expenses>0&&<div className="rounded-xl bg-[var(--bg)] p-4"><div className="text-xs text-[var(--muted)]">Gastos</div><div className="mt-1 text-lg font-bold">{money(expenses)}</div><ChangeLabel current={expenses} previous={previousExpenseTotal}/></div>}{previousSales>0&&sales>0&&previousIngredientCosts>0&&ingredientCosts>0&&<div className="rounded-xl bg-[var(--bg)] p-4"><div className="text-xs text-[var(--muted)]">Ventas después de insumos</div><div className="mt-1 text-lg font-bold">{money(netAfterIngredients)}</div><ChangeLabel current={netAfterIngredients} previous={previousSales-previousIngredientCosts}/></div>}</div></Card>:null}
   <Card className="p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="serif text-xl font-semibold">Gastos del período</h2><p className="mt-1 text-sm text-[var(--muted)]">{money(expenses)} registrados por vos.</p></div><Button onClick={()=>setExpenseModal('new')}><Plus size={16}/> Agregar gasto</Button></div>{categories.length?<button className="mt-4 w-full text-left" onClick={()=>setExpenseList(true)}><div className="space-y-2">{categories.map(([k,v]:any)=>{const pct=expenses?(v/expenses)*100:0;return <div key={k}><div className="flex justify-between text-xs"><span>{k}</span><b>{pct.toFixed(0)}%</b></div><div className="mt-1 h-2 rounded-full bg-[var(--bg)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{width:`${pct}%`}}/></div></div>})}</div><div className="mt-3 text-xs font-semibold text-[var(--primary)]">Tocá para ver el historial →</div></button>:<div className="mt-4 rounded-xl bg-[var(--bg)] p-4"><EmptyState title="No tenés gastos registrados todavía." text="Registrá gastos reales del negocio para ver el desglose por categoría."/></div>}</Card>
   {top.length>0&&<Card className="p-5"><h2 className="serif text-xl font-semibold">Productos más vendidos</h2><div className="mt-4 space-y-3">{top.map(([name,count]:any)=><div key={name}><div className="flex justify-between text-sm"><span>{name}</span><b>{count} unidades · {money(productSales[name]||0)}</b></div><div className="mt-1 h-2 rounded-full bg-[var(--bg)]"><div className="h-full rounded-full bg-[var(--primary)]" style={{width:`${(count/max)*100}%`}}/></div></div>)}</div></Card>}
   <Card className="p-5"><button className="w-full text-left" onClick={()=>setPendingList(true)}><div className="flex items-center justify-between gap-3"><div><h2 className="serif text-xl font-semibold">Pendiente de cobro</h2><p className="mt-1 text-sm text-[var(--muted)]">{pendingOrders.length?`${pendingOrders.length} pedido${pendingOrders.length===1?'':'s'} con saldo pendiente`:'No hay pedidos con saldo pendiente'}</p></div><div className="text-right"><div className="text-xl font-bold">{money(pendingTotal)}</div><div className="text-xs font-semibold text-[var(--primary)]">Ver pedidos →</div></div></div></button></Card>
   {expenseModal&&<ExpenseModal initial={expenseModal==='new'?null:expenseModal} onClose={()=>setExpenseModal(null)} onSave={saveExpense}/>} {expenseList&&<ExpenseListModal expenses={periodExpenses} onClose={()=>setExpenseList(false)} onEdit={e=>{setExpenseList(false);setExpenseModal(e)}} onDelete={deleteExpense}/>} {pendingList&&<PendingOrdersModal orders={pendingOrders} onClose={()=>setPendingList(false)}/>} 
 </div>
}

export function Profile({data,update,onToast,onTheme}:any){const [f,setF]=useState({...data.businessProfile});const [u,setU]=useState({...data.userProfile});function save(){const now=new Date().toISOString();update((d:AppData)=>({...d,businessProfile:{...f,updatedAt:now},userProfile:{...u,updatedAt:now}}));onToast("Datos guardados")};return <div className="space-y-5"><PageHeader title="Mi perfil" subtitle="Mi cuenta, mi negocio y apariencia."/><Card className="p-5"><div className="mb-4 flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-full bg-[var(--accent)] font-bold text-white">{(u.name||f.businessName||"R")[0].toUpperCase()}</div><div><div className="font-semibold">{u.name||"Tu perfil"}</div><div className="text-xs text-[var(--muted)]">Información local del usuario</div></div></div><div className="space-y-4"><Input label="Nombre" value={u.name} onChange={(e:any)=>setU({...u,name:e.target.value})}/><Input label="Email" value={u.email} onChange={(e:any)=>setU({...u,email:e.target.value})}/><Input label="Nombre del negocio" value={f.businessName} onChange={(e:any)=>setF({...f,businessName:e.target.value})}/><Input label="Teléfono" value={f.phone} onChange={(e:any)=>setF({...f,phone:e.target.value})}/><Input label="Dirección" value={f.address} onChange={(e:any)=>setF({...f,address:e.target.value})}/><Textarea label="Información adicional" value={f.additionalInfo} onChange={(e:any)=>setF({...f,additionalInfo:e.target.value})}/><Button onClick={save}>Guardar cambios</Button></div></Card><Card className="p-5"><h2 className="serif text-xl font-semibold">Apariencia</h2><div className="mt-3 grid grid-cols-3 gap-2">{[["light","Claro"],["dark","Oscuro"],["system","Sistema"]].map(([id,label])=><button key={id} onClick={()=>onTheme(id)} className={`rounded-xl border p-3 text-sm ${data.settings.theme===id?"border-[var(--primary)] bg-[var(--bg)]":"border-[var(--border)]"}`}>{label}</button>)}</div></Card><Card className="p-5"><h2 className="font-semibold">Datos locales</h2><p className="mt-1 text-sm text-[var(--muted)]">Tus datos se guardan únicamente en este dispositivo.</p><div className="mt-4 flex flex-wrap gap-2"><Button variant="ghost" onClick={()=>{if(confirm("¿Restaurar datos de ejemplo? Se reemplazarán los datos actuales.")){restoreDemoData(createDemoData());location.reload()}}}>Restaurar datos de ejemplo</Button><Button variant="danger" onClick={()=>{if(confirm("¿Eliminar todos los datos locales? Esta acción no se puede deshacer.")){clearData();location.reload()}}}>Eliminar todos mis datos</Button></div></Card></div>}

export function PageHeader({title,subtitle,action,back,onBack}:any){return <div className="flex items-start justify-between gap-3"><div className="min-w-0 flex-1"><div className="flex items-center gap-2">{back&&<button aria-label="Volver" onClick={onBack} className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-[var(--border)] bg-[var(--surface)] hover:bg-[var(--bg)]"><ArrowLeft size={19}/></button>}<h1 className="serif text-3xl font-bold">{title}</h1></div><p className="mt-1 max-w-[34rem] text-sm leading-5 text-[var(--muted)]">{subtitle}</p></div>{action&&<div className="page-header-action shrink-0">{action}</div>}</div>}
export function Notifications({data,update,onClose}:any){const notes=data.notifications;function read(id:string){update((d:AppData)=>({...d,notifications:d.notifications.map(n=>n.id===id?{...n,read:true}:n)}))};return <Modal title="Notificaciones" onClose={onClose} footer={<Button variant="ghost" onClick={()=>update((d:AppData)=>({...d,notifications:d.notifications.map(n=>({...n,read:true}))}))}>Marcar todas como leídas</Button>}><div className="space-y-2">{notes.length?notes.map((n:any)=><button key={n.id} onClick={()=>read(n.id)} className={`w-full rounded-xl border p-3 text-left ${n.read?"border-[var(--border)] opacity-60":"border-[var(--primary)] bg-[var(--bg)]"}`}><div className="font-semibold">{n.title}</div><div className="text-sm text-[var(--muted)]">{n.message}</div></button>):<EmptyState title="Sin notificaciones" text="Acá aparecerán eventos importantes del negocio."/>}</div></Modal>}
